(1, 'Facilities', '1. Apakah ada fasilitas antar jemput untuk peserta didik? Ya, ada. Lokasi rumah akan disurvei oleh penanggung jawab antar jemput sekolah untuk menentukan apakah rute tersebut sudah tersedia layanan antar jemputnya. Layanan ini dapat disediakan jika kuota minimal 5 anak dalam rute tersebut terpenuhi. Apabila lokasi rumah belum tersedia layanan antar jemput sekolah, orang tua dipersilahkan untuk melakukan alternatif antar jemput secara pribadi. Orang tua membayar iuran bulanan khusus untuk fasilitas antar jemput. 2. Apakah ada fasilitas catering untuk peserta didik? PRIMARY/JUNIOR HIGH/SENIOR HIGH Ya, ada, sekolah bekerjasama dengan beberapa pengelola catering yang memberikan pelayanan catering peserta didik yang dapat dipilih oleh orang tua. Dengan menghubungi langsung pengelola catering untuk melakukan pemesanan dan pembayaran. 3. Apakah Perguruan GIS memiliki cabang sekolah lain? Ya perguruan GIS memiliki 3 cabang yaitu : 1. GIS Condet yang beralamat di Jl. Condet Raya no. 5 Kramat Jati Jakarta Timur No telp : (021) 80884510 (hunting) (021) 8094416 2. GIS Serpong dengan alamat Jl. Puspiptek Raya Buaran &ndash; Serpong, Tangerang Selatan. No telp: (021) 75870770. Dimana setiap cabang memiliki 4 unit lengkap yaitu PG-K, SD, SMP,dan SMA. 3. GIS Jogja (akan&nbsp;launching&nbsp;di tahun pelajaran 2021-2022)\r\n', 1, '8fe495ee4a89494ea7bd116f4e24401c.jpg'),
(2, 'Curriculum', 'CURRICULUM 1. Kurikulum apa yang digunakan? &bull; GIS menggunakan kurikulum nasional plus, kurikulum 2013 dengan pengayaan empat pilar pembelajaran GIS yaitu akademik, keislaman, keglobalan dan kepemimpinan yang dirancang sesuai dengan visi, misi GIS dan perkembangan zaman. &bull; Pengayaan pada intrakurikuler dilakukan dengan pengembangan struktur kurikulum, seperti penambahan jam pelajaran, materi ajar, dan kegiatan pembelajaran dengan penggunaan dua bahasa yaitu Indonesia dan Inggris sebagai English classroom instructions, serta internalisasi nilai keislaman dalam pembelajaran. &bull; Pengayaan pada kokurikuler dilakukan dengan pengembangan kegiatan pengembangan 4 pilar pendidikan, seperti : PG-K : City tour, pengenalan profesi, kultur sekolah, dan sebagainya yang mendukung intrakurikuler. PRIMARY : Field trip, perayaan hari besar Islam, Super camp, kultur sekolah, dan sebagainya yang mendukung intrakurikuler. JUNIOR HIGH : Field trip, perayaan hari besar Islam, book report, research paper, kultur sekolah, dan sebagainya yang mendukung intrakurikuler. SENIOR HIGH : Field trip, Perayaan hari besar Islam, seminar, enterpreneurship, kultur sekolah, dan sebagainya yang mendukung intrakurikuler. 2. Bagaimana penanaman dan pendidikan Agama Islam dilakukan di GIS? &bull; Pemahaman agama diberikan berdasarkan Qur&rsquo;an dan Sunnah tanpa berafiliasi dengan aliran tertentu. PG-K &bull; Penanaman agama Islam dilakukan terintegrasi dalam intrakurikuler baik dalam materi pembelajaran tematik maupun pembiasaan praktik ibadah serta amal soleh. Contoh penanaman agama dalam intrakurikuler dilakukan dengan mengulang do&rsquo;a harian, surat pendek dan mendengarkan kisah-kisah teladan saat circle time (di pagi hari). Pembiasaan praktik ibadah dan amal soleh dilakukan dengan praktik shalat harian, sholat dhuha di masjid (setiap minggu pertama), berinfaq dan penggunaan seragam muslim setiap hari Jum&rsquo;at. &bull; Penanaman keagamaan dalam kokurikuler dilakukan dengan pengembangan berbagai kegiatan seperti, manasik haji, berbuka puasa bersama, pawai muharam, dan maulid fair sebagai penguatan keislaman. PRIMARY &bull; Penanaman agama Islam dilakukan terintegrasi dalam intrakurikuler dengan pengembangan jam belajar, materi pembelajaran dan mata pelajaran maupun pembiasaan praktik ibadah serta amal soleh. Contoh penanaman agama dalam intrakurikuler dilakukan dengan Mata Pelajaran Pendidikan Agama Islam diberikan 2 kali pertemuan setiap pekan, pelajaran Al Qur&rsquo;an 3 kali pertemuan setiap pekan untuk bacaan dan hafalan /tahfidz juz 30, ikrar, mengulang do&rsquo;a harian dan surat pendek, shalat wajib (dhuhur dan ashar) berjamaah, shalat dhuha, berinfaq, penggunaan seragam muslim setiap hari Jum&rsquo;at, program Pejuang Subuh dan Hijab Motion untuk siswa kelas 5 dan 6. &bull; Pengembangan kokurikuler untuk penanaman agama dilakukan dengan pengembangan kegiatan seperti buka puasa bersama, pesantren Ramadhan, peringatan hari besar Islam, manasik haji, Jum&rsquo;at bersih, pengenalan bahasa Arab sebagai penguatan keislaman. JUNIOR HIGH &bull; Penanaman agama Islam terintegrasi dalam intrakurikuler dilakukan dengan penambahan jam belajar, materi pembelajaran, mata pelajaran maupun pembiasaan praktik ibadah serta amal soleh. Contoh penanaman agama pada intrakurikuler yang dilakukan dengan Pendidikan Agama Islam diberikan 3 jam pelajaran, pelajaran Al Qur&rsquo;an 2 jam pelajaran, target hafalan 1 juz, pembiasaan ibadah seperti pelaksanaan wudhu, shalat wajib (dhuhur dan ashar) berjamaah, shalat dhuha, tadarus Qur&rsquo;an, puasa Ramadhan. &bull; Penanaman keislaman dalam kokurikuler yang dilakukan dengan pengembangan kegiatan seperti pesantren Ramadhan, program Pejuang Subuh dan Hijab Motion, peringatan hari besar Islam, dan lomba-lomba ketrampilan agama (Islamic Competition) seperti lomba ceramah agama, MTQ, nasyid, azan, tahfidz, dan lainnya. Bagaimana jika anak saya belum bisa membaca Al Qur&rsquo;an? Akan diberikan matrikulasi oleh guru Agama, dan orangtua diminta bekerjasama untuk mengajarkan di rumah. &emsp; SENIOR HIGH &bull; Penanaman agama Islam dilakukan terintegrasi dalam intrakurikuler dalam bentuk penambahan jam belajar, materi pembelajaran, mata pelajaran maupun pembiasaan praktik ibadah serta amal soleh. Contoh pengembangan intrakurikuler yang dilakukan seperti Pendidikan Agama Islam diberikan 3 jam pelajaran, pelajaran Al Qur&rsquo;an 2 jam pelajaran dengan target hafalan sebanyak 1 Juz, pembiasaan ibadah seperti pelaksanaan wudhu, shalat wajib (dhuhur dan ashar) berjamaah, shalat dhuha, tadarus Qur&rsquo;an, puasa Ramadhan, pembiasaan seragam muslim setiap hari. &bull; Penanaman keislaman dalam kokurikuler dilakukan dengan pengembangan kegiatan pesantren Ramadhan, peringatan hari besar Islam, kultum dhuha dan lomba-lomba ketrampilan agama (Islamic Competition) seperti lomba ceramah agama, MTQ, nasyid, azan, tahfidz, dll. Bagaimana jika anak saya belum bisa membaca Al Qur&rsquo;an? Akan diberikan matrikulasi oleh guru Agama, dan orangtua diminta bekerjasama untuk mengajarkan di rumah. 3. Bagaimana pengembangan program Bahasa Inggris dilakukan di GIS? PGK Program bahasa Inggris dilakukan dengan penggunaan English classroom instruction dan pembelajaran bahasa Inggris oleh guru bidang studi serta ESL teacher sekali dalam sepekan. Dua kali (Selasa dan Kamis) dalam satu pekan siswa distimulasi untuk berkomunikasi dalam bahasa Inggris dengan penggunaan pin I Speak English dan penggunaan media pembelajaran lainnya dalam bahasa Inggris. PRIMARY Program bahasa Inggris dilakukan dalam bentuk penggunaan instruksi kelas dalam bahasa Inggris (English class room instruction), pelajaran Bahasa Inggris yang diberikan 2 kali dalam satu pekan dan 1 kali dalam satu pekan bersama ESL teacher. Untuk pelajaran Math, Science, dan ICT disampaikan dalam bahasa Inggris. Dua kali (Selasa dan Kamis) dalam satu pekan seluruh guru dan siswa berkomunikasi dalam bahasa Inggris di area sekolah dengan penggunaan pin I Speak English. JUNIOR HIGH Program bahasa Inggris dilakukan dalam bentuk penggunaan instruksi kelas dalam bahasa Inggris (English class room instructions), pelajaran Bahasa Inggris yang diberikan sebanyak 4 jam pelajaran dalam satu pekan dan 2 jam pelajaran dalam satu pekan dengan ESL teacher, serta beberapa pelajaran yang disampaikan dalam bahasa Inggris seperti, Social Studies. Selain itu program pembiasaan diluar kelas terdiri dari English movement, yaitu kegiatan pembiasaan ketrampilan berbahasa Inggris seperti news reading, reading poetry, reading corner, student led conference, English competition serta program unggulan homestay ke luar negeri. Dan dua kali (Selasa dan Kamis) dalam satu pekan, setiap guru dan siswa wajib berkomunikasi dalam Bahasa Inggris di area sekolah dengan penggunaan pin I Speak English. SENIOR HIGH Program bahasa Inggris dilakukan dalam bentuk penggunaan instruksi kelas dalam bahasa Inggris (English class room instruction), pelajaran Bahasa Inggris yang diberikan 2 kali dalam satu pekan dan 1 kali dalam satu pekan dengan ESL teacher, serta beberapa pelajaran yang menggunakan buku resources dalam bahasa Inggris dan adanya program English day 2 hari dalam 1 pekan, student presentation (Project Based Learning) dan English Debate Competition. Serta program unggulan homestay ke luar negeri. 4. Selain pelajaran yang sudah ada, apakah ada kegiatan lain untuk pengembangan kepribadian dan kepemimpinan anak? Ya, GIS sangat concern terhadap tumbuh kembang kepribadian dan kepemimpinan anak. Hal ini dapat dilihat dari berbagai kegiatan berikut: PG-K &bull; Kokurikuler : city tour, pawai Muharam, pekan budaya, GIS Market, kunjungan edukatif, outbond, pentas seni, cooking session, renang, makan sehat bersama, pentas seni, family day, home visit, puncak tema, father&rsquo;s day. &bull; Ekstrakurikuler : di bidang seni (vocal, tari dan menggambar) dan olah raga (futsal dan karate) sesuai jadwal masing &ndash; masing selama 45-60 menit di jam akhir pembelajaran. PRIMARY &bull; Kokurikuler : orientasi peserta didik baru, ethnic show, teater tanah airku, selera nusantara market day, pendidikan demokrasi, peringatan hari anak nasional, family gathering, peringatan hari besar Islam, kunjungan edukatif, buka puasa bersama, pesantren Ramadhan, pendidikan Aqil Baligh, Kepemimpinan/Leadership (Outbond kelas 1 dan 2, supercamp kelas 3, gladian kelas 4, camping kelas 5, tahfidz graduation Juz 30 grade 3), khataman Al &ndash;Qur&rsquo;an, manasik haji, presentasi karya tulis, wisuda. &bull; Ekstrakurikuler : di bidang seni (tari dan paduan suara), olah raga (panahan, futsal, basket, karate, taekwondo dan renang) maupun ilmu pengetahuan seperti qiroah dan pramuka sebagai ekstrakurikuler wajib, yang dilakukan sesuai jadwal masing &ndash; masing sesudah jam pembelajaran berakhir. JUNIOR HIGH &bull; Kokurikuler : LDKS (Latihan Dasar Kepemimpinan Peserta didik), upacara bendera, field trip, pesantren Ramadhan, english competition, islamic competition, giscup, lomba eksternal, keputrian, seminar pendidikan seksualitas, anti pornografi, , bahaya merokok, bahaya HIV/AIDS, peringatan hari besar Islam, khatmul qur&rsquo;an, razia, tes urine, penulisan karya tulis, presentasi karya tulis, wisuda. &bull; Ekstrakurikuler : di bidang seni (paduan suara, tari saman, melukis), olah raga (panahan, futsal, basket, badminton, karate), keilmuan (Islamic Science Club) yang dilakukan sesuai jadwal masing &ndash; masing dimulai jam 16.15-17.30. SENIOR HIGH &bull; Kokurikuler : Latihan Dasar Kepemimpinan Peserta didik (LDKS), Field Trip, Peringatan Hari Besar Islam (PHBI), Peringatan Hari Besar Nasional (PHBN), Pesantren Ramadhan, OSIS, Cyber team, Go Green team dan Rohis, Sport day, achivement motivation program, santunan anak yatim, bakti sosial. &bull; Ekstrakurikuler : di bidang seni (tari saman, band), olah raga (futsal, basket, bulutangkis, panahan), Pramuka, Paskibra, dan Cyber. 5. Kemana biasanya lulusan GIS melanjutkan pendidikannya? PG-K 99-100% peserta didik melanjutkan ke Primary GIS. PRIMARY Sebagian besar melanjutkan ke Junior High GIS dan JUNIOR HIGH Negeri unggulan, sebagian melanjutkan ke pesantren dan boarding school. JUNIOR HIGH Sebagian besar melanjutkan ke Junior High GIS dan SMA Negeri unggulan. sebagian melanjutkan ke pesantren dan boarding school. SENIOR HIGH Untuk lulusan telah tersebar ke berbagai Perguruan Tinggi favorit seperti UI, UGM, UNDIP, UNBRAW, ITS dan lainnya, serta ke PTS favorit seperti BINUS, Prasetya Mulya, Telkom University, Trisakti, Paramadina. Beberapa siswa melanjutkan ke luar negeri. Adapun prosentase rata-rata penyebarannya adalah : &plusmn;30% PTN, &plusmn;60% PTS, &plusmn;10% Akademi. 6. Bagaimana GIS menyelenggarakan Virtual Learning? GIS bekerjasama dengan Kayreach System Indonesia dalam menyediakan Zoom Education sebagai platform digital learning. PG-K 1. Pembelajaran dilakukan dengan interaktif menggunakan berbagai aplikasi digital, seperti Zoom, Google Classroom, Quizziz, Kahoot, Youtube dan Drive in Learning. 2. Pendidik dilengkapi dengan perangkat online learning seperti akses internet, webcam dan headset. 3. Kegiatan kesiswaan pengembangan 4 Pilar Pendidikan Khas GIS tetap berjalan secara daring, seperti ikrar, hafalan surat pendek, do&#39;a harian dan hadits, praktik salat, dan pengembangan 6 aspek anak. 4. Waktu pembelajaran jarak jauh jam 08.00-10.00 PRIMARY 1. Pembelajaran dilakukan dengan interaktif menggunakan berbagai aplikasi digital, seperti Zoom, Google Classroom, Quizziz, Kahoot, Youtube. 2. Pendidik dilengkapi dengan perangkat online learning seperti akses internet, webcam dan headset. 3. Kegiatan kesiswaan pengembangan 4 Pilar Pendidikan Khas GIS tetap berjalan secara daring, seperti ikrar, Salat Dhuha, Salat Zuhur, pramuka, student paper report, Jum&rsquo;at Bersih (kegiatan dokter kecil) 4. Waktu pembelajaran jarak jauh : Kelas 1-3 jam 08.00-10.00 Kelas 4-6 jam 07.30 &ndash; 12.30 JUNIOR HIGH 1. Pembelajaran dilakukan dengan interaktif menggunakan berbagai aplikasi digital, seperti Zoom, Google Classroom, Quizziz, Kahoot, Youtube. 2. Pendidik dilengkapi dengan perangkat online learning seperti akses internet, webcam dan headset. 3. Kegiatan kesiswaan pengembangan 4 Pilar Pendidikan Khas GIS tetap berjalan secara daring, seperti ikrar, Salat Dhuha, Salat Zuhur, muhadharah/kultum, hafalan juz 30, karya tulis ilmiah, kegiatan OSIS, webinar, literasi, Jum&rsquo;at Bersih. 4. Waktu pembelajaran jarak jauh 07.30 &ndash; 13.10 SENIOR HIGH 1. Pembelajaran dilakukan dengan interaktif menggunakan berbagai aplikasi digital, seperti Zoom, Google Classroom, Quizziz, Kahoot, Youtube. 2. Pendidik dilengkapi dengan perangkat online learning seperti akses internet, webcam dan headset. 3. Kegiatan kesiswaan pengembangan 4 Pilar Pendidikan Khas GIS tetap berjalan secara daring, seperti ikrar, tadarus, Salat Dhuha, Salat Zuhur, muhadharah/kultum, kegiatan OSIS, webinar, research paper, literasi, Presentasi Project Based Learning (PBL), upacara bendera. 4. Waktu pembelajaran jarak jauh jam 07.30 &ndash; 14.00\r\n', 1, '5343f6e68b48d44ca7805be7990dbb0e.jpeg'),
(4, 'Admission', '1.Mengapa memilih Global Islamic School? &quot;GIS membina peserta didik secara holistic dan integrative meliputi intelektual maupun spiritual dalam pembelajaran, pembentukan sikap, pengembangan kemampuan dasar, serta pengembangan minat dan bakat yang diwujudkan dalam setiap proses pembelajarannya baik intrakurikuler, kokurikuler dan ekstrakurikuler. &quot;Dalam pembelajaran intrakurikuler, kokurikuler dan ekstrakurikuler tersebut menerapkan 4 pilar pendidikan khas GIS yang terdiri dari: pilar akademik, keislaman, keglobalan dan kepemimpinan. &quot;Kapasitas kelas maksimal dengan rasio guru yang memadai sehingga dapat melakukan pemantauan dengan baik terhadap peserta didik. &bull; Play group : 15 siswa didampingi 2 orang guru &bull; Kindergarten : 20 siswa didampingi 2 orang guru &bull; Primary : 24 siswa didampingi 2 orang guru &bull; Junior High : 24 siswa didampingi guru mata pelajaran, wali kelas dan guru BK &bull; Senior High : 24 siswa didampingi guru mata pelajaran, wali kelas dan guru BK GIS memiliki fasilitas yang mendukung proses pembelajaran. Pendidik dan tenaga kependidikan memiliki dedikasi, berjiwa muda, energik &amp; kreatif serta cerdas, jujur, marhamah, tanggung jawab dan cakap berkomunikasi (GIS core values) 2.Bagaimana status akreditasi GIS? PG-K Hasil akreditasi terakhir tanggal 2 Oktober 2019 memperoleh nilai klasifikasi 93 peringkat A. PRIMARY Hasil akreditasi terakhir tanggal 16 September 2016 memperoleh nilai klasifikasi 94 peringkat A. JUNIOR HIGH Hasil akreditasi terakhir tanggal 16 September 2016 memperoleh nilai klasifikasi 97 peringkat A. SENIOR HIGH Hasil akreditasi terakhir tanggal 21 Oktober 2019 memperoleh nilai klasifikasi 95 peringkat A. 3.Sebelum calon peserta didik diterima, test apakah yang wajib diikuti? PG-K &bull; Observasi tumbuh kembang (Personal Development Review) yaitu pengamatan terhadap kesiapan diri anak, kematangan emosi, ketrampilan sosial dan keterampilan motorik dalam mengikuti pembelajaran yang bersifat formal guna mengetahui tingkat kemampuan dasar skolastik, kemampuan kebahasaan, kemampuan numerik dan kemampuan spasial (gambar). &bull; Interviu Orang Tua Wawancara langsung untuk mengetahui latar belakang keluarga calon peserta didik baru, serta bentuk kerja sama yang disepakati antara pihak sekolah dan orang tua. Pada saat peserta didik mengikuti tes seleksi, orang tua calon peserta didik mengisi kuesioner ditempat yang telah ditentukan. PRIMARY &bull; Observasi perkembangan kognitif. Yaitu observasi untuk mengetahui tingkat kemampuan dasar skolastik yang meliputi kemampuan kebahasaan, kemampuan numerik, dan kemampuan spasial (gambar). &bull; Observasi kematangan diri. yaitu pengamatan terhadap gaya belajar anak, kesiapan diri anak, kematangan emosi, ketrampilan sosial, dan ketrampilan motorik dalam mengikuti pembelajaran yang bersifat formal. &bull; Interviu Orang Tua. Wawancara langsung untuk mengetahui latar belakang keluarga calon peserta didik baru, serta bentuk kerja sama yang disepakati antara pihak sekolah dan orang tua. Pada saat peserta didik mengikuti tes seleksi, orang tua calon peserta didik mengisi kuesioner ditempat yang telah ditentukan. JUNIOR HIGH &bull; Tes psikologi Yaitu serangkaian tes yang dilakukan oleh Psikolog untuk menilai konstruksi psikologis, seperti fungsi kognitif dan emosional calon peserta didik. &quot;Tes akademik &bull; Yaitu tes pengetahuan umum dengan batasan materi kurikulum kelas 6 Primary yang dilakukan secara online (computer based test) meliputi beberapa mata pelajaran, seperti : Bahasa Indonesia, Bahasa Inggris, Matematika, IPA. &bull; Interviu Wawancara berbahasa Inggris guru dengan calon peserta didik untuk mendapatkan informasi tentang profil pribadi calon peserta didik. &bull; Pada saat peserta didik mengikuti tes seleksi, orang tua calon peserta didik mengisi kuesioner ditempat yang telah ditentukan. SENIOR HIGH &bull; Tes psikologi Yaitu serangkaian tes yang dilakukan oleh Psikolog untuk menilai konstruksi psikologis, seperti fungsi kognitif dan emosional calon peserta didik. &bull; Tes akademik Yaitu tes pengetahuan umum dengan batasan materi kurikulum kelas 9 JUNIOR HIGH yang dilakukan secara online (computer based test) meliputi beberapa mata pelajaran, seperti : Bahasa Indonesia, Bahasa Inggris, Matematika, IPA, IPS. &bull; Interviu Wawancara berbahasa Inggris guru dengan calon peserta didik untuk mendapatkan informasi tentang profil pribadi calon peserta didik. Pada saat peserta didik mengikuti tes seleksi, orang tua calon peserta didik mengisi kuesioner ditempat yang telah ditentukan. Apa dasar yang digunakan untuk peminatan peserta didik? SMA GIS memiliki 2 peminatan yaitu IPA dan IPS dengan kuota 3 kelas IPA dan 2 kelas IPS. Peminatan didasarkan dari nilai rapor, nilai tes seleksi dan rekomendasi Guru BK JUNIOR HIGH (jika ada dan diperlukan). 4.Bagaimanakah proses pendaftaran siswa baru di GIS? Pendaftaran dilakukan dengan cara mengakses www.global-islamic.com melalui PC atau mobile phone, klik Menu Admission dan selanjutnya mengikuti mekanisme yang tersedia. 5.Berapakah batas usia untuk masuk sekolah? &bull; PG-K Batas usia minimal calon peserta didik pada Juli 2020 adalah 3 tahun. Peserta didik yang berusia 2,10 tahun pada Juli 2020 diperkenankan daftar dan mengikuti tes. Proses penerimaan akan tetap berdasarkan seleksi serta kesediaan memenuhi persyaratan yang ditentukan oleh sekolah. &bull; PRIMARY Batas usia minimal calon peserta didik pada Juli 2020 adalah 6 tahun. Peserta didik yang berusia 5, 10 tahun pada Juli 2020 diperkenankan daftar dan mengikuti tes. Proses penerimaan akan tetap berdasarkan seleksi serta kesediaan memenuhi persyaratan yang ditentukan oleh sekolah. &bull; JUNIOR Tidak ada batas usia minimal, tetapi batasan maksimum mengikuti aturan dinas. &bull; SENIOR Tidak ada batas usia minimal, tetapi batasan maksimum mengikuti aturan dinas. 6.Apakah GIS menerima peserta didik pindahan? &bull; PGK Ketika kapasitas memungkinkan dan calon peserta didik memenuhi syarat yang ditentukan oleh sekolah, maka peserta didik pindahan dapat diterima. &bull; PRIMARY Ketika kapasitas memungkinkan untuk peserta didik kelas 1, 2, 3, 4 dan calon peserta didik memenuhi syarat yang ditentukan oleh sekolah, maka peserta didik pindahan dapat diterima. Kelas 5 dan 6 tidak menerima siswa pindahan. Karena, target pencapaian kelulusan sesuai standar GIS tidak dapat dicapai dengan waktu 1-2 tahun. &bull; JUNIOR HIGH Ketika kapasitas memungkinkan untuk peserta didik kelas 7, 8 dan calon peserta didik memenuhi syarat yang ditentukan oleh sekolah, maka peserta didik pindahan dapat diterima, namun tidak menerima peserta didik pindahan di kelas 9. Karena, target pencapaian kelulusan sesuai standar GIS tidak dapat dicapai dengan waktu 1 tahun. &bull; SENIOR HIGH Ketika kapasitas memungkinkan untuk peserta didik kelas 11 dan calon peserta didik memenuhi syarat yang ditentukan oleh sekolah, maka peserta didik pindahan dapat diterima. Namun, untuk kelas 12 tidak menerima pindahan. Karena, target pencapaian kelulusan sesuai standar GIS tidak dapat dicapai dengan waktu 1 tahun. Bagaimana prosedur siswa pindahan? Untuk unit Primary, Junior, Senior : a. Mutasi satu wilayah b. Mutasi beda provinsi c. Mutasi dari pesantren/PKBM d. Mutasi luar negeri Berlaku ketentuan mutasi dari dinas Pendidikan di tahun berjalan 7.Bagaimanakah mekanisme tes PPDB online? PGK &bull; Calon peserta didik diberikan link Zoom oleh panitia sebelum jadwal test yang telah ditentukan &bull; Pada hari H jadwal test, calon peserta didik masuk link Zoom &bull; Setiap calon peserta didik akan diobservasi oleh guru dan psikolog dengan rasio 1 : 1 secara bergantian. PRIMARY &bull; Calon peserta didik diberikan link Zoom oleh panitia sebelum jadwal test yang telah ditentukan &bull; Pada hari H jadwal test, calon peserta didik masuk link Zoom &bull; Setiap calon peserta didik akan diobservasi oleh guru dan psikolog dengan rasio 1 : 1 secara bergantian. JUNIOR HIGH Calon peserta didik mengakses www.smpgisjakarta.com. Setelah akses dibuka kemuadian log in dengan mengisi user name dan password menggunakan no peserta test yang sudah dibagikan. Kemudian akan muncul soal PPDB dan klik soal tersebut, kerjakan dan submit jika sudah selesai. SENIOR HIGH Calon peserta didik mengakses www.smagisjakarta.com. Setelah akses dibuka kemuadian log in dengan mengisi user name dan password menggunakan no peserta test yang sudah dibagikan. Kemudian akan muncul soal PPDB dan klik soal tersebut, kerjakan dan submit jika sudah selesai. 8.Apakah komponen biaya yang harus dibayarkan? Uang pangkal dibayarkan 1 kali selama menjadi peserta didik di salah satu unit sekolah GIS. (Siswa PG GIS yang melanjutkan ke jenjang TK GIS, tidak perlu membayar uang pangkal) Uang perlengkapan (seragam dan buku/tollkit) dibayarkan 1 kali pada tahun pelajaran pertama siswa sekolah. Selanjutnya setiap tahun ajaran siswa membeli buku pelajaran sesuai levelnya. Uang kegiatan dibayarkan setiap tahun pelajaran sesuai levelnya. Uang BKOMG (Badan Koordinasi Orang Tua dan Guru) dibayarkan setiap tahun pelajaran. Iuran SPP dibayarkan setiap bulan. Besaran SPP sesuai tahun pelajaran siswa tersebut masuk sekolah dan tidak ada kenaikan sampai siswa lulus dari jenjang tersebut. Kecuali ada kebijakan terkait inflasi. Iuran ekstrakurikuler dibayarkan setiap semester bagi peserta didik yang mengikuti. Untuk PG-K dibayarkan per term (9-10 kali pertemuan) Iuran antar - jemput dibayarkan setiap bulan bagi peserta didik yang mengikuti. Iuran catering dibayarkan setiap bulan bagi peserta didik Primary, Junior, dan Senior yang mengikuti. 9.Apakah ada potongan biaya bila calon peserta didik berasal dari GIS? Ya, potongan diberikan untuk peserta didik GIS yang melanjutkan ke jenjang pendidikan ke unit pendidikan berikutnya sebesar 5 % dari uang pangkal. 10.Apakah ada potongan biaya untuk 2 calon peserta didik bersaudara kandung yang masuk di tahun ajaran yang sama? Ya, dengan menunjukkan bukti yang bisa dipertanggung jawabkan (Akte dan KK) saudara kandung yang masuk pada tahun ajaran yang sama baik di unit sekolah yang sama atau berbeda mendapat potongan harga masing - masing 5 % dari uang pangkal. 11.Apakah ada beasiswa/potongan biaya untuk peserta didik berprestasi yang berasal dari GIS? Ya, dengan menunjukkan SK kepala sekolah, peserta didik yang berprestasi dari unit PRIMARY/JUNIOR HIGH GIS yang melanjutkan ke unit berikutnya mendapat potongan biaya sebagai berikut: &bull; Peringkat I : bebas uang pangkal 100% &bull; Peringkat II : bebas uang pangkal 80% &bull; Peringkat III : bebas uang pangkal 70% &bull; Peringkat IV sampai dengan X : 50%.\r\n', 1, '467f4c38cafc9577c8d0bc33989ca8c2.png');

