(1, 'f2cae6d91069f799653f34db46436725.png', 'SMP Islam Al-Hadiriyah', 'Duren Sawit', 'Jakarta Timur', 'Jl. Buaran I Kav. PTB Blok. L3 No. 6-8 Kel. Klender Kec. Duren Sawit Jakarta Timur', '02128536735', 'smpalhadiriyah@gmail.com', 'SMP Islam Al-Hadiriyah', 'https://maps.app.goo.gl/ErRjCPm7RJCXnPRz7', '083822404696', 'smpalhadiriyah', '8d4e8ce77595a8485724bf77d4d4b640.JPG', '<p>Terbentuknya generasi cerdas, kreatif, dan unggul yang berwawasan global dalam menyongsong masa depan</p>\r\n', '<p>1. Mewujudkan sistem pembelajaran aktif, kreatif, efektif, dan mengedepankan serta menerapkan sistem penilaian multi dimensi yang terpadu</p>\r\n\r\n<p>2. Mengembangkan program - program pembinaan dan pendidikan terpadu berbasis IQ, TQ, dan&nbsp; SQ agar dapat bersaing di dunia global</p>\r\n\r\n<p>3. Mewujudkan tenaga pendidik dan tenaga kependidikan yang profesional&nbsp;</p>\r\n\r\n<p>4. Menyelenggarakan pendidikan yang komprehensif dengan manajemen sekolah yang unggul&nbsp;</p>\r\n\r\n<p>5. Mewujudkan sarana dan prasarana pembelajaran yang lengkap dengan kualitas dan kreativitas yang memadai</p>\r\n\r\n<p>6. Mengintegrasi nilai islami,&nbsp; dan akhlaqul karimah diseluruh aktifitas sekolah</p>\r\n', '53c5c7b5bb9c55698f0537fe787980a0.png', 'Kami Menyambut baik adanya Website Sekolah ini , dengan dipublikasinya website sekolah ini Harapannya dapat meningkatkan layanan pendidikan kepada siswa, orangtua, dan masyarakat pada umumnya semakin meningkat. ', '<p>Welcome to the official website of Al-Hadiriyah Islamic Junior High School, an information and communication platform created to strengthen the relationship between the school, parents, and the community in order to achieve quality education grounded in Islamic values.</p>\r\n\r\n<p>As an Islamic educational institution, Al-Hadiriyah Islamic Junior High School is committed to producing a generation that is intellectually intelligent, morally strong, and steadfast in faith. Upholding the values of &quot;<em>Knowledge, Faith, and Deed</em>&quot; we equip students with competitive academic knowledge, Islamic character development, and 21st-century skills to prepare them to face the challenges of the times. Therefore, let us work together to educate and nurture our children into a generation that is knowledgeable, civilized, and makes a positive contribution to the community and nation.</p>\r\n', '0a54ce8c4305010eb3c0dd855601b3f7.jpg', 'https://forms.gle/6eb4SbQuRwUhYSPn7', 'SMP Islam Al-Hadiriyah');

