(31, 'TERAPI JUS BUAH DAN SAYUR', '<p>Sebelum kita mengetahui bagaimana cara kerja jus buah dan sayur dalam menyembuhkan penyakit maka kita harus mengetahui dulu penyakit yang ada pada tubuh kita. Penyakit tubuh berarti gangguan yang terjadi pada tubuh. Misalnya, gangguan ginjal disebut penyakit ginjal, gangguan pada jantung disebut penyakit jantung, gangguan pada hati berarti penyakit hati, dan begitupun seterunya. Salah satu penyebab munculnya penyakit adalah pola makan kita yang cenderung memakan siap jadi, instan, asal kenyang saja. Apa yang kita makan akan menjadi penentu Kesehatan pada tubuh kita secara keseluruhan. Selain pola makan, penyebab lainnya yaitu lingkungan. Sebagian besar kita lingkungan sekitar masih banyak yang suka buang sampah sembarang, polusi udara makin meningkat dan Kawasan hijau makin berkurang sehingga.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Adapun pola hidup yang sehat adalah. (1) berolahraga, kita harus sering-sering berolahraga walaupun sehari sekitar 10-30 menit. (2) pola makan sehat, kita harus menghindar makanan siap saji apa lagi yang instan. (3) intirahat yang cukup, tubuh kita juga butuh istirahat jangan terlalu menforsi tubuh kita untuk bekerja tanpa istirajat.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Terapi jus merupakan metode penyembuhan penyakit secara alami, selain itu dapat mencegah munculnya penyakit.&nbsp; Ada dua alasan yang melatar belakangi terapi jus buah dan sayur, pertama; kandungan nutrisi yang dimili buah dan sayur. Buah dan sayuran merupakan sumber makan yang mengandung nutri lengkap dan sehat, selain itu mengandun juga zat gizi berupa vitamin dan mineral sebagai komponen utama. Buah dan sayur juga mengandunng serat makanan, enzimm, dan fitonutrisen. Warna-warni buah dan sayur merupakan informasi kandungan nutrisi. Buah dan sayur memiliki warna yang berbeda mengandung nutrisi yang berbeda-beda. Warna hijau pada buah dan sayur hijau terbentuk klorofil, makin pekat atau gelap warna hijau, maka kandungan vitamin dan mineral makin banyak. Warna merah buah dan sayuran oleh anosianin dan likopen. Warna biru atau ungu yang ada pada buah dan sayur dibentuk oleh senyawa antosianin, berguna untuk menghambat terbentuknya gumpalan dalam pembulu darah. Warna putih pada buah dan sayur mempunyai kandungan serat dan vitamin C yang tinggi. Warna kuning pada buah dan sayur bisa mencegah penyakit jantung coroner dan penyakit stroke. Warna jingga yang ada pada buah dan sayur Adalah indikasi dari kandungan nutrisi dominan dan alfa karoten. Kedua; Kelebihan metode jus dalam mengonsumsi buah dan sayur. Sebaiknya kita mengonsumsi 5 sampai 9 porsi buah dan sayur sehari. Mungkin hal ini sulit dilakukan banyak orang makan kita dapat membuat jus. Dengan begitu kita mudah mengonsumsu buah dan sayur dengan meminum saripati dan dapat membantu meringankan saluran cerna.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Salah satu penyakit yang dapat disembuhkan dengan jus yaitu penyakit anemia, jus untuk menyembuhkan penyakit anemia antara lain jus banan peach, jus semangka kuning, jus&nbsp; kelapa muda, jus brokoli melon, jus wortel bawang mentimun, jus bit nanas, jus apel bayam, jus bit anggur, jus bit apel seledri, jus pisang avocado, jus bayam petenseli, jus alpukat susu dan jus bayam madu. Dan masih banyak jenis penyakit yang dapat disembuhkan dengan meminum jus buah dan sayur.</p>\r\n\r\n<p><br />\r\n<br />\r\nPenulis,<br />\r\nIta Purnamasari, S.Pd</p>\r\n', '2025-08-28 06:41:27', 1, 'Pendidikan', 106, '54d00ebd15e4d9ea3399171371e4dcf0.png', 1, 'Admin', 0, 'terapi-jus-buah-dan-sayur'),
(33, 'THIBBIL QULUB ', '<p>Perhatian Islam terhadap kondisi hati manusia menempati posisi yang sangat penting, sebab hati (qalb) bukan hanya sekadar organ biologis, melainkan pusat kesadaran spiritual, moral, dan intelektual. Para ulama seperti al-Ghazali menjelaskan bahwa hati adalah latifah rabbaniyyah, yaitu dimensi ruhani yang mengendalikan seluruh perilaku manusia. Dengan demikian, kesehatan hati menjadi indikator utama baik buruknya amal perbuatan seseorang, sebagaimana Nabi Muhammad SAW menegaskan dalam hadist:</p>\r\n\r\n<p>&ldquo;Ketahuilah, sesungguhnya di dalam tubuh ada segumpal daging. jika ia baik, maka seluruh tubuh akan baik, dan jika ia rusak, maka seluruh tubuh akan rusak. Ketahuilah, segumpal daging itu adalah hati.&rdquo; (HR. Bukhari dan Muslim)</p>\r\n\r\n<p>Selain itu, kesehatan hati juga menjadi jawaban atas tantangan terkini yang dihadapi manusia modern, seperti krisis identitas, kecemasan, serta ketergantungan pada hiburan duniawi sering kali tidak mampu memberi ketenangan batin. Padahal Allah SWT menegaskan dalam Al-Qur&rsquo;an bahwa ketenangan hati hanya dapat diperoleh dengan mengingat Allah SWT.&nbsp; &ldquo;(Yaitu) orang-orang yang beriman dan hati mereka menjadi tenteram dengan mengingat Allah. Ingatlah, bahwa hanya dengan mengingat Allah hati akan selalu tenteram.&rdquo; (Q.S. Ar Rad: 28)</p>\r\n\r\n<p>Hal ini menunjukkan bahwa kualitas individu manusia merupakan dampak dari kemampuan dalam merawat hati, bukan hanya sekedar merawat fisik. Untuk menjaga kesehatan hati, penting untuk menumbuhkan kesadaran spiritual. Selain penting dari sudut pandang teologis, hal ini memiliki manfaat dalam membantu mengembangkan karakter moral, integritas, dan kapasitas umat Islam untuk menghadapi dilema etika di era globalisasi. Oleh karena itu, fondasi keimanan dan ketakwaan perlu diperkuat melalui pembahasan mendalam yang berkelanjutan tentang kesehatan hati.</p>\r\n\r\n<p><strong>Definisi Hati</strong>:</p>\r\n\r\n<ol>\r\n	<li><strong>Imam Al-Ghazali</strong>: Hati (qalb) adalah suatu hakikat ruhani yang halus (latifah rabbaniyyah) yang berkaitan dengan jasmani manusia. Hati merupakan pusat kesadaran, pengetahuan, dan tempat terbitnya niat, sehingga menjadi penentu baik atau buruknya perbuatan seseorang. Hal ini menunjukkan adanya keterkaitan antara aspek ruhani dan jasmani dalam diri manusia. Hati dalam makna ruhani berfungsi mengendalikan perilaku lahiriah, sedangkan hati dalam makna biologis berperan dalam menjaga kehidupan fisik. Ketika hati ruhani ini dipenuhi cahaya iman, maka anggota tubuh akan mengikuti dengan amal Sholeh. Begitupun sebaliknya, jika hati kotor oleh penyakit batin, maka perilaku yang muncul akan cenderung menyimpang (Al-Ghazali, 2023).</li>\r\n	<li><strong>Ibnu Qayyim Al-Zaujiyyah</strong>: Hati adalah raja bagi seluruh anggota tubuh. Jika hati baik, maka seluruh anggota tubuh akan baik dan jika hati rusak, maka seluruh tubuh pun akan rusak. Hati memiliki dua fungsi utama, yaitu sebagai pusat keyakinan dan pusat kemauan (iradah). Hati berperan mengarahkan kehendak manusia kepada kebaikan atau keburukan. Kehendak inilah yang kemudian mendorong anggota tubuh untuk beramal (Ibn Qoyyim, 2018).</li>\r\n	<li><strong>Imam An-Nawawi</strong>: Hati sebagai tempat bertumpunya niat dan keikhlasan. Hati menentukan diterima atau tidaknya amal, karena Allah melihat pada hati dan amal, bukan pada rupa dan bentuk f isik. Dengan demikian, segala amal manusia pada hakikatnya bergantung pada kondisi hati yang melandasinya (An-Nawawi, 2022).</li>\r\n</ol>\r\n\r\n<p><strong>Kedudukan Hati:</strong></p>\r\n\r\n<ol>\r\n	<li><strong>Hati yang Sehat:</strong> Hati yang sehat adalah hati yang bersih, yakni hati yang harus dimiliki seseorang agar selamat ketika menghadap Allah SWT. Hati yang sehat disebut sebagai Qolbun Salim. Sebagaimana firman Allah SWT dalam Al-Qur&rsquo;an:&nbsp;&ldquo;(Yaitu) di hari harta dan anak-anak laki-laki tidak berguna, kecuali orang-orang yang menghadap Allah dengan hati yang bersih.&rdquo; (Q.S. Asy-Syu&#39;araa&#39;: 88-89).&nbsp;Nabi Muhammad SAW juga mengatakan dalam hadistnya bahwa kemuliaan manusia dilihat dari kesucian hati dan amalnya.&nbsp;&ldquo;Sesungguhnya Allah tidak melihat kepada bentuk badan atau rupa kalian, tetapi Dia melihat terhadap hati kalian dan amal kalian.&rdquo; (H.R. Muslim). Para ulama banyak mengartikan kata Qolbun Salim, diantaranya yaitu: (a)Ibnu Qoyyim Al-Jauziyyah Al-Qalb as-salim merupakan hati yang bersih dari syahwat yang menentang perintah dan larangan Allah dan dari syubhat yang bertentangan dengan firman Nya (Ibn Qoyyim, 2018). (b)Imam An-Nawawi Al-Qalb as-salim adalah hati yang bebas dari syirik, riya, hasad, kebencian, dan penyakit batin lainnya. Amal yang dilakukan dengan hati bersih akan diterima Allah, sedangkan amal yang tercampur niat buruk tidak memiliki nilai di sisi-Nya An-Nawawi, 2022). (c)Imam Al-Ghazali Al-Qalb as-salim merupakan hati yang menjaga integritas spiritual dengan ikhlas, konsisten dalam dzikir, dan penuh niat tulus hanya karena Allah SWT (Al-Ghazali, 2023). Berdasarkan hal tersebut, maka dapat disimpulkan bahwa Hati yang sepenuhnya suci dari segala bentuk penyimpangan keyakinan, penyakit batin, dan dorongan nafsu yang bertentangan dengan kehendak Allah. Hati ini bersih dari syirik, riya, hasad, kebencian, serta bebas dari syubhat yang menyesatkan. Ia terjaga melalui keikhlasan, keteguhan dalam dzikir, dan niat tulus semata-mata untuk Allah, sehingga setiap amal yang lahir darinya bernilai tinggi di sisi-Nya dan menjadi jalan menuju keselamatan akhirat.</li>\r\n	<li><strong>Hati yang Mati</strong>:&nbsp;Hati yang mati adalah hati yang terkunci, tidak bisa menerima nasehat, dan tidak dapat menerima petunjuk hidayah dari Allah SWT. Sebagimana firman Allah SWT dalam Al Qur&rsquo;an:&nbsp;&ldquo;Allah telah mengunci hati dan pendengaran mereka. Pada penglihatan mereka ada penutup, dan bagi mereka azab yang sangat berat.&rdquo; (Q.S. Al-Baqarah: 7) Ayat tersebut menunjukkan bahwa penguncian hati dan alat indra manusia disebabkan karena hati yang dibiarkan sehingga tidak digunakan untuk memahami ayat-ayat Allah SWT. Dalam surat lain, Allah SWT berfirman:&nbsp;&ldquo;...Mereka memiliki hati yang tidak mereka pergunakan untuk memahami (ayat-ayat Allah) dan memiliki mata yang tidak mereka pergunakan untuk melihat (ayat-ayat Allah), serta memiliki telinga yang tidak mereka pergunakan untuk mendengarkan (ayat-ayat Allah). Mereka seperti hewan ternak, bahkan lebih sesat lagi. Mereka itulah orang-orang yang lengah.&rdquo; (Q.S. Al-A&rsquo;raf: 179).</li>\r\n	<li><strong>Hati yang Sakit</strong>:&nbsp;Hati jenis ketiga adalah hati yang hidup namun terkena penyakit. Di dalamnya terdapat dua kekuatan yang saling memengaruhi, di mana kadang salah satu kekuatan lebih dominan dan menarik hati tersebut ke arahnya. Allah SWT berfirman dalam Al-Qur&rsquo;an:&nbsp;&ldquo;Dalam hati mereka ada penyakit, lalu Allah menambah penyakitnya dan mereka mendapat azab yang sangat pedih karena mereka selalu berdusta..&rdquo; (Q.S. Al-Baqarah: 10). Hal ini memperlihatkan posisi manusia yang memiliki penyakit hati. Mereka akan berada pada kekuatan cinta kepada Allah SWT yang mengajaknya Kembali pada ajaran Allah SWT dan Rosul-Nya. Disisi lain mereka beraad pada kekuatan cinta kepada syahwatnya yang selalu mengajak pada kenikmatan dunia yang sesaat.&nbsp;</li>\r\n</ol>\r\n\r\n<p>Dengan demikian, materi ini menegaskan bahwa inti dari kebahagiaan dan keselamatan manusia terletak pada kondisi batin yang murni. Hati yang sehat (qalbun salim) menjadi kunci diterimanya amal, sumber ketenangan jiwa, serta jalan menuju ridha Allah. Sebaliknya, hati yang sakit atau mati menjadikan manusia terjerumus dalam kesesatan, meskipun secara lahiriah ia tampak beramal. Oleh karena itu, upaya merawat hati melalui dzikir, ikhlas, muhasabah, dan menjauhi penyakit batin merupakan kebutuhan mendasar bagi seorang Muslim.</p>\r\n', '2025-11-05 08:02:24', 1, 'Pendidikan', 34, 'cdee2302ee763c621eb57eb6e99c0f3f.jpeg', 1, 'Admin', 0, 'thibbil-qulub'),
(34, 'Millenial Girl’s Guidebook', '<p><strong>Definisi Cantik</strong></p>\r\n\r\n<p>Banyak orang beranggapan bahwa cantik adalah tubuh yang ramping, wajah yang menawan, polesan wajah serasi, serta pakaian yang mengikuti perkembangan mode. Batasan cantik sering didefinisikan seperti itu, sehingga semua orang tenggelam di dalamnya dan berlomba-lomba untuk menjadi yang tercantik atas itu semua. Padahal seharusnya seorang perempuan mempunyai pijakan yang membuat mereka yakin bahwa cantik bukan sekedar polesan wajah dan gaya yang memesona.</p>\r\n\r\n<p>Cantik adalah ketika kita membuat seseorang di sekitar kita merasa bahagia dengan kehadiran kita. Itulah keadaan cantik yang sebenarnya, keadaan yang kekal dan tidak tergantikan oleh polesan apa pun, karena setiap orang akan mengingat kecantikan perempuan tersebut.</p>\r\n\r\n<p>Hingga sekarang memang belum ada yang dapat dengan jelas mendefiniskan cantik karena sifatnya yang relatif dan bergantung dengan selera. Sebagaimana juga bahwa cantik didefinisikan tergantung dari sudut pandang setiap pribadi dalam mengartikannya. Tentu saja, kita akan terlihat cantik di pandangan atau mata seseorang yang tepat. Pada dasarnya seseorang cantik bagaimana dan siapa yang memandang.</p>\r\n\r\n<p>Cantik tak hanya berdasarkan apa yang kita lihat melalui kasat mata karena tidak semua dianugerafi kecantikan fisik yang sesuai dengan standar. Cantik juga diterapkan pada kecerdasan intelegensi dan emosional sehingga dapat mewakili perilaku positif dan mengesankan serta terpancar kecantikannya.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Definisi Cantik Menurut Beberapa Negara</strong></p>\r\n\r\n<p>Berikut ini adalah beberapa definisi cantik di dunia yang diambil dari republika.co.id</p>\r\n\r\n<ul>\r\n	<li><strong>Burma</strong>: Cantik menurut Burma, tepatnya menurut perempuan Kayan, adalah perempuan dengan leher panjang, atau sering disebut sebagai perempuan jerapah.</li>\r\n	<li><strong>Brasil</strong>: Perempuan bertubuh gitar adalah perempuan cantik sebagai tanda kesehatan dan kekayaan.</li>\r\n	<li><strong>Korea</strong>: Bedah plastik adalah sebuah kewajaran, mereka rela menahan sakit demi berdiam beberapa jam di meja operasi untuk membuat mata lebih lebar dan bulat.</li>\r\n	<li><strong>Eropa</strong>: Di bagian Eropa, tampilan alami yang dianggap paling cantik bahkan hanya dengan sedikit <em>make up</em> saja.</li>\r\n	<li><strong>Afrika</strong>:<strong>&nbsp;</strong>Perempuan yang dianggap cantik pada negara ini adalah perempuan yang memiliki berat badan berlebih dan gemuk tubuhnya.</li>\r\n	<li><strong>Cina</strong>: Pada negara ini kecantikan terletak pada kaki. Mereka rela melakukan proses pemanjangan yang menyakitkan yang membentang tulang untuk membuat kaki menjadi lebih tinggi.</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong><em>Brain, Beauty, Behavior</em></strong></p>\r\n\r\n<p>Beauty, brain, dan behavior merupakan suatu konsep yang sering digunakan untuk mengukur performa perempuan. Dalam setiap kontes kecantikan, ketiga hal ini selalu menjadi acuan standar.</p>\r\n\r\n<p><em>Beauty</em> merupakan apa yang tampak oleh mata. Dalam kehidupan sehari-hari kita sering sekali melihat gambaran seseorang perempuan melalui internet, tv, majalah seorang perempuan yang digambarkan memiliki tubuh yang indah, kulit yang mulus, rambut panjang lurus dan sebagainya. Beberapa media telah mencetak bahwa standar kecantikan perempuan itu sama rata seperti yang digambarkan. Kemudian banyak sekali perempuan-perempuan yang merasa tertinggal oleh mode, lalu memaksakan diri untuk tampil cantik seperti yang ditampilkan media. Sehingga membuat keunikan diri sendiri menjadi hilang. Sebenarnya berpenampilan cantik tidak harus mengikuti mode. Penampilan menarik adalah penampilan yang sejujurnya serta dapat menempatkan diri di mana kita berada.</p>\r\n\r\n<p><em>Brain</em> dapat diartikan bermacam-macam. Namun brain dapat kita artikan sebagai pengetahuan yang luas. Perempuan yang menarik adalah perempuan yang ketika kita berbicara terasa nyaman karena memiliki hikmat, solusi, serta kebenaran untuk memecahkan suatu persoalan. Brain disini ialah seorang perempuan yang memiliki kecerdasan, perempuan yang dapat berpikir dengan kritis serta perempuan yang memiliki pengetahuan atau pandangan yang luas. Sehingga, brain disini sangat dibutuhkan sebagai seorang perempuan yang cantik.</p>\r\n\r\n<p><em>Behavior, </em>merupakan tingkah laku atau sikap yang jarang kita sadari. Seperti misalkan kita berperilaku sopan atau berperilaku kurang baik dan itu hanyalah seseorang yang dapat menilai, sehingga kita sulit untuk menyadari sikap kita sendiri. Tingkah laku dibentuk oleh latar belakang keluarga, budaya, pendidikan serta lingkungan sekitar kita. Sehingga perilaku atau tingkah laku kita adalah bagaimana kita dibesarkan dan berada di tempat yang tepat atau tidak. Perempuan cantik umumnya juga memiliki tingkah laku yang baik, peduli terhadap sesama, memiliki empati, dan tentunya juga memiliki hati yang baik serta hangat.</p>\r\n\r\n<p>Brain, Beauty and Behavior adalah perempuan yang memiliki pemikiran kritis dengan kecerdasan serta penampilan yang rapi dan menarik dengan perilaku/tingkah laku yang baik juga kepada banyak orang. Cantik tidak hanya dari fisik, cantik juga tentu memiliki hati dan sikap yang baik.</p>\r\n', '2025-11-06 02:19:35', 1, 'Pendidikan', 30, '1dc6ef446c147e05117652232b57d1db.jpeg', 1, 'Admin', 0, 'millenial-girls-guidebook'),
(35, 'Titik Terendah', '<p>Titik Terendah dalam Kehidupan terkadang membuat orang lain buta seakan bahwa hidup akan mati besok dan semangat membara dihati menjadi padam tak tau arah pulang&nbsp; dan tak tau tujuan. Sebagaimana dalam buku yang saya baca &ldquo;Ketika Aku tak tau apa yang Ku inginkan&rdquo;</p>\r\n\r\n<p>&ldquo;<strong><em>Layaknya kesedihan dan rasa sakit yang memiliki banyak bentuk, kita pun perlu bentuk penghiburan yang beragam. Kita perlu menghibur diri sendiri , perlu juga penghiburan dari orang lain. Akan sangat baik ketika kita punya teman di kala kita sedang merasa kesulitan. Meski mereka tidak sepenuhnya bisa mengerti semua isi pikiran kita, tapi hanya dengan mengeluarkan isi hati saja sudah menjadi penghiburan bagi bagi diri sendiri, begitu pula sebaliknya ketika kita sedang menghibur seseorang, kita pun sebenarnya sudah mendapat penghiburan. Penghiburan adalah cara sesama untuk saling berbagi perasaan. Asalkan disertai ketulusan, penghiburan bisa jadi penenang hati bagi semua orang&rdquo;</em></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>Ketika Aku Tak Tahu Apa Yang Aku Inginkan.</em></p>\r\n\r\n<p><strong><em>Kalimat-kalimat kehidupan yang mengembalikan diriku yang hilang.</em></strong></p>\r\n\r\n<p><strong><em>Apa yang benar-benar aku inginkan? Apakah aku sudah hidup dengan benar? Bagaimana aku harus menjalani hidup ke depannya? Kehidupan laksana rangkaian pertanyaan yang tiada berakhir. Menemukan jawabannya dengan kekuatan sendiri tidaklah mudah.</em></strong></p>\r\n\r\n<p><strong><em>Mengapa hatiku selalu merasa sepi dan hampa?</em></strong></p>\r\n\r\n<p><strong><em>Mengapa bertemu orang lain menjadi hal yang melelahkan?</em></strong></p>\r\n\r\n<p><strong><em>Mengapa aku tidak merasa bahagia padahal sudah menjalani hidup dengan sebaik-baiknya?</em></strong></p>\r\n\r\n<p><strong><em>Apakah hidup tanpa jiwa seperti ini bisa disebut kehidupan</em></strong><em>?</em></p>\r\n\r\n<p><em>Kalau pertanyaan-pertanyaan seperti itu terus berputar di kepala, kita jadi kelelahan dan kehilangan semangat melakukan segala hal. Kita bisa jadi sering menangis tiba-tiba. Tangisan itu muncul dari luapan emosi kita yang terpendam ketika menjani hari-hari yang sibuk&mdash;tak punya waktu untuk menenangkan hati dan tubuh yang letih atau memikirkan jawaban atas pertanyaan-pertanyaan tersebut.</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>Lalu aku mendengar tausiyah yang disampaikan oleh Ustadzah, maka ku kobinasikan perasaan dan juga hati akan </em></p>\r\n\r\n<p><em>KUTIPAN CERAMAH USTADZAH AISYAH BIN SYEIKH ABU BAKAR:</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>Dari IMAM AL JUNAID BAGHDADI: </em></p>\r\n\r\n<p><em>Jika BESOK &ndash;BESOK Allah mengujimu</em></p>\r\n\r\n<p><em>Kalau Kita Mau&nbsp; Tahu Ini Siksa, </em></p>\r\n\r\n<p><em>Penggugur Dosa, Atau Ini Adalah Meninggikan Derajat , Cukup Lihat Bagaimana Respon Mu Dalam Menyikapi Terhadap Ujian Itu. Maka Nilai Sendiri , Bila Responmu Marah? Allah Sedang&nbsp; Marah Padamu, Bila Responmu Sabar Allah Sedang Menggugurkan Dosa-dosamu, Bila Responmu Sabar Penuh Keikhlasan, Keridoan, Maka Allah Ridho Kepadamu</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>JAWABANNYA ADALAH: </em></p>\r\n\r\n<p><em>ADA DALAM BUKU </em></p>\r\n\r\n<p><em>HIDUP DAMAI TANPA </em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>Kita hanya perlu berusaha untuk menjadi diri kita</em></p>\r\n\r\n<p><em>sebagai seseorang yang lebih baik dengan menjadi </em></p>\r\n\r\n<p><em>seseorang yang pantas mendapatkan kebahagiaan</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>Banyak orang suka membandingkan diri mereka dengan orang lain, mulai dari prestasi, kekayaan, keindahan fisik, sehingga kualitas hidup secara umum. Namun , seringkali kita lupa bahwa hidup bukanlah kompetisi dan setiap orang memiliki jalan hidup dan keunikan mereka sendiri.</em></p>\r\n\r\n<p><em>Biasanya kita membandingkan, output-nya pasti selalu negatif. Ada perasaan inferior ketika melihat prestasi orang lain. </em></p>\r\n\r\n<p><em>Namun, apakah membandingkan diri selalu negatif? Jawabannya tergantung, bisa ya bisa juga tidak.</em></p>\r\n\r\n<p><em>Ketika melihat orang, pertanyaannya adalah apakah kita menjadi terpacu untuk menggembangkan diri menjadi versi terbaik ataukah memilih menyalahkan diri dari keadaan? Kamu yang sedang berada di posisi ini, istirahatlah sebentar dan bacalah buku ini sebagai pengingat bahwa tak apa dengan kamu yang sekarang. Tak ada yang perlu dimenangkan , goals-nya ada di kamu.</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><em>MAKA KENALILAH DIRIMU SENDIRI = BUKU&nbsp; OMG THAT&rsquo;S ME</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Kita hanya perlu berusaha untuk menjadikan diri kita sebagai seseorang yang pantas mendapatkan kebahagiaan.</p>\r\n\r\n<p>KEBAHAGIAAN KITA YANG BUAT&nbsp; BUKAN ORANG</p>\r\n', '2025-11-06 03:12:27', 1, 'Pendidikan', 40, '105f38a7b6425991960f6b12eed0b485.jpeg', 1, 'Admin', 0, 'titik-terendah'),
(36, 'SELF LOVE', '<p>Dalam kehidupan yang penuh dengan tuntutan, tekanan sosial, serta standar keberhasilan yang sering kali ditentukan oleh orang lain, banyak individu lupa untuk menghargai dirinya sendiri. Fenomena ini kerap membuat seseorang merasa tidak cukup baik, selalu membandingkan diri dengan orang lain, dan akhirnya kehilangan makna kebahagiaan. Oleh karena itu, <em>self love</em> atau cinta terhadap diri sendiri menjadi hal yang sangat penting untuk dipahami dan dipraktikkan dalam kehidupan sehari-hari.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Definisi Self Love </strong></p>\r\n\r\n<p>Self Love merupakan perasaan penghargaan terhadap diri sendiri yang berkembang dari perilaku yang mendorong perkembangan mental, emosional, dan spiritual. <em>Self love</em> bukanlah bentuk egoisme atau sikap mementingkan diri sendiri secara berlebihan. Sebaliknya, ia adalah kesadaran bahwa setiap individu berhak dihargai, dihormati, dan dicintai, termasuk oleh dirinya sendiri. Mencintai diri berarti menerima segala kelebihan dan kekurangan yang ada, serta memberikan ruang untuk tumbuh menjadi pribadi yang lebih baik.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Pentingnya Self Love </strong></p>\r\n\r\n<p>Self-love adalah sebuah fondasi yang memungkinkan kita untuk bersikap tegas, menjalin hubungan yang sehat dengan orang lain. Tidak hanya bermanfaat untuk membuat Anda merasa tenang dalam menjalani hidup, self-love juga memiliki berbagai manfaat yaitu Kepuasan hidup yang lebih besar, Dapat mendorong kita untuk mengambil kebiasaan baik (mencintai tubuh, jiwa, dan pikiran), Menciptakan Kesehatan mental yang lebih baik</p>\r\n\r\n<p>Tidak kalah penting, <em>self love</em> juga berkaitan erat dengan bagaimana kita memperlakukan kegagalan. Banyak orang merasa rendah diri ketika menghadapi kegagalan, padahal kegagalan adalah bagian alami dari proses belajar. Dengan mencintai diri, seseorang akan mampu memandang kegagalan sebagai pelajaran, bukan sebagai akhir dari segalanya. Sikap inilah yang kemudian menumbuhkan ketangguhan serta optimisme dalam menjalani kehidupan.</p>\r\n\r\n<p>Lebih jauh, <em>self love</em> akan membawa dampak positif pada hubungan dengan orang lain. Seseorang yang mampu menghargai dirinya sendiri cenderung lebih tulus dalam menjalin interaksi, karena ia tidak bergantung pada pengakuan eksternal untuk merasa berharga. Ia dapat berbagi kasih sayang, empati, serta kebaikan dengan cara yang lebih sehat.</p>\r\n\r\n<p>Ada beberapa hal yang perlu diperhatikan sebelum mempraktikan self love :</p>\r\n\r\n<ul>\r\n	<li>Pikirkan <em>self love</em> sebagai Pratik, bukan tujuan</li>\r\n	<li>Anda dapat mencintai diri seniri tanpa mencintai dunia anda</li>\r\n	<li>Tantang narasi mental negative and dengan tetap berpegang pada fakta</li>\r\n	<li>Rasa sakit dan ketidakadilan dapat membuat mencintai diri sendiri jauh lebih sulit</li>\r\n	<li>Berlatihlah menetapkan batasan&nbsp; untuk membangun harga diri</li>\r\n	<li>Mencintai diri sendiri Adalah pengejaran yang berharga</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Cara mempraktikan self love</strong></p>\r\n\r\n<p>Salah satu wujud nyata dari <em>self love</em> adalah merawat kesehatan, baik fisik maupun mental. Pola hidup sehat, istirahat cukup, serta menjaga pikiran agar tetap positif merupakan bentuk penghargaan terhadap diri. Selain itu, <em>self love</em> juga berarti menetapkan batasan (<em>boundaries</em>). Ketika seseorang mampu mengatakan &ldquo;tidak&rdquo; terhadap hal-hal yang merugikan dirinya, itu merupakan tanda bahwa ia menghargai kebutuhan dan kenyamanan pribadinya, selain itu kita juga bisa menerapkan berbagai cara untuk mempraktikan self love sebagai berikut :</p>\r\n\r\n<ul>\r\n	<li>Menjadi sadar. Orang yang lebih mencintai diri sendiri cenderung mengetahui apa yang mereka pikirkan, rasakan, dan inginkan.</li>\r\n	<li>Mengambil Tindakan berdasarkan kebutuhan daripada keinginan. Dengan tetap Mempraktikan perawatan diri yang baik, artinya&nbsp; orang yang memiliki self love yang tinggi akan memberikan &lsquo;makan&rsquo; untuk dirinya&nbsp; sendiri setiap hari melalui aktivitas yang sehat, seperti makan nutrisi yang baik, olahraga, tidur yang cukup, keintiman, dan interaksi social yang sehat.</li>\r\n	<li>Memberi ruang untuk kebiasan sehat.&nbsp; Dengan mulailah merawat diri dengan memperhatikan apa yang di makan, bagaimana anda berolahraga.</li>\r\n	<li>Selalu bersikap baik, sabar, lembut, dan penuh kasih pada diri sendiri,seperti apa yang anda lakukan terhadap orang lain yang anda sayangi.</li>\r\n	<li>Me time</li>\r\n	<li>Memaafkan kesalahan orang lain</li>\r\n	<li>Menjauh dari orang-orang yang membawa pengaruh Buruk</li>\r\n	<li>Fokus</li>\r\n</ul>\r\n\r\n<p>Kesimpulannya, <em>self love</em> adalah pondasi penting dalam membangun kehidupan yang bahagia dan seimbang. Dengan mencintai diri sendiri, seseorang tidak hanya menjaga kesehatannya, tetapi juga mengembangkan rasa percaya diri dan sikap optimis dalam menghadapi tantangan hidup. Oleh sebab itu, sudah sepatutnya setiap individu belajar untuk lebih menghargai dirinya, karena mencintai diri bukanlah pilihan, melainkan kebutuhan untuk mencapai kesejahteraan sejati.</p>\r\n', '2025-11-06 03:18:53', 1, 'Pendidikan', 36, 'f5ea82d7f0f3593d16a7cc4d4c094ab2.jpeg', 1, 'Admin', 0, 'self-love'),
(37, 'Rahasia Awet Muda', '<p>Setiap orang mendambakan hidup yang panjang dan berkualitas, dan rahasia untuk <strong>Awet Muda</strong> sejati terletak pada penerapan <strong>Pola Hidup Sehat</strong> secara konsisten. Pola hidup sehat bukan hanya sekedar mengkonsumsi makanan yang sehat, tetapi juga memperhatikan kandungan zat aditif dari makanan, cara memasak makanan tersebut dan juga selalu konsisten dalam berolahraga. Dalam artikel ini akan mengulas berbagai aspek penuaan, mulai dari ciri-cirinya hingga faktor penyebab dan langkah-langkah yang bisa diambil untuk mempertahankan kesehatan dan vitalitas tubuh seperti kebugaran dan kecantikan.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Penuaan memengaruhi tubuh secara eksternal dan internal. Ciri-ciri penuaan ada yang terlihat dan tersembunyi seperti bermanifestasi menjadi masalah kesehatan. Beberapa tanda penuaan yang seringkali terlihat pada kulit meliputi:</p>\r\n\r\n<ul>\r\n	<li>Kulit Kering, Kasar, dan Mengelupas</li>\r\n	<li>Garis Halus, Kerutan, dan Kulit Kendur</li>\r\n	<li>Kantung Mata dan Lingkaran Gelap di Bawah Mata</li>\r\n</ul>\r\n\r\n<p>Salah satu tanda penuaan yang berbentuk masalah kesehatan adalah nyeri punggung dan tulang<strong> </strong>yang dapat berhubungan dengan kondisi seperti <strong>Osteoporosis</strong>. Osteoporosis adalah kondisi yang memengaruhi kepadatan tulang, mengubah struktur tulang normal menjadi tulang yang keropos. Terdapat faktor-faktor untama penyebab penuaan yang dapat bersumber dari eksternal&nbsp; diantaranya:</p>\r\n\r\n<ol>\r\n	<li><strong>Paparan Sinar Matahari:</strong> Paparan berlebihan dapat merusak kulit dan mempercepat penuaan</li>\r\n	<li><strong>Kebiasaan Buruk:</strong> Merokok (rokok dan cerutu) dan konsumsi alkohol dapat berdampak negatif.</li>\r\n	<li><strong>Gaya Hidup Sedentari (Kurang Gerak) dan Diet Tidak Sehat:</strong> Hal ini sering kali berkontribusi pada kelebihan berat badan.</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Faktor-faktor ini terkait erat dengan kondisi internal yang membantu dalam mempercepat proses penuaan dini. Faktor internal yang sangat mempengaruhi adalah Radikal bebas akan memicu <em>stress oksidatif</em>. dan juga kadar <em>AGEs (Advanced Glycation End-products). </em>Radikal bebas adalah sebutan untuk sel-sel yang rusak; ia adalah atom atau molekul tidak stabil yang hanya memiliki satu elektron dan akan menarik elektron dari molekul lain dalam tubuh, mengubahnya menjadi radikal bebas juga, yang menyebabkan kerusakan sel. Pembentukan radikal bebas dipicu oleh banyak faktor termasuk sinar UV, polusi udara, merokok, dan gangguan metabolism. Ketika tubuh mengalami kondisi ketidakseimbangan antara produksi radikal bebas (spesies oksigen reaktif atau ROS) dan kemampuan tubuh untuk menetralisirnya menggunakan antioksidan maka akan menyebabkan tubuh mengalami stress oksidatif. Ketika mengalami <em>stress oksidatif</em> maka dapat merusak sel dan jaringan, yang merupakan faktor risiko berbagai penyakit kronis (seperti kanker dan penyakit jantung) dan terkait dengan proses penuaan.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Tubuh memiliki sistem untuk menetralisir radikal bebas menggunakan antioksidan. Antioksidan adalah molekul yang cukup stabil untuk mendonasikan elektron ke radikal bebas, sehingga menstabilkannya. Kadar <em>AGEs (Advanced Glycation End-products</em>) adalah molekul berbahaya yang terbentuk dari interaksi antara gula dengan protein atau lemak dalam tubuh. AGEs terbentuk secara alami seiring bertambahnya usia, namun juga dapat dihasilkan dari makanan yang dimasak pada suhu tinggi. Kadar AGEs yang tinggi dikaitkan dengan peningkatan risiko penyakit kronis (seperti diabetes dan penyakit jantung), peradangan, dan <em>stres oksidatif</em><em>.</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Terdapat beberapa tips dan trik agar kita selalu sehat, awet muda dan terhindar dari penuaan dini diantaranya :</p>\r\n\r\n<ol>\r\n	<li>Nutrisi dan Pola Makan Sehat: (a)&nbsp;<strong>Pola Makan Seimbang:</strong> Terapkan prinsip &quot;Menu 4 Sehat 5 Sempurna,&quot; yang mencakup Makanan Pokok, Lauk Pauk, Sayur Mayur, Buah-buahan, dan Susu. (b)&nbsp;<strong>Tingkatkan Antioksidan:</strong> Konsumsi banyak buah dan sayur karena kaya akan antioksidan dan enzim pencernaan. (c)&nbsp;<strong>Batasi Konsumsi Natrium (Garam):</strong> Asupan natrium yang berlebihan menyebabkan retensi cairan dan meningkatkan volume darah, yang membebani jantung dan menaikkan tekanan darah, berpotensi menyebabkan hipertensi, penyakit kardiovaskular, dan penyakit ginjal. (d)&nbsp;<strong>Perhatikan Cara Memasak:</strong> Kurangi metode memasak seperti menggoreng atau memanggang dengan suhu yang sangat tinggi. Memasak pada suhu tinggi dapat membentuk senyawa berbahaya: (1)&nbsp;<strong>Akrilamida:</strong> Terbentuk saat gula dan asam amino bereaksi pada suhu tinggi dalam makanan (misalnya kentang atau sereal) dan diklasifikasikan sebagai karsinogen. (2)&nbsp;<strong>Amina Heterosiklik (HCA) dan Hidrokarbon Aromatik Polisiklik (PAH):</strong> Terbentuk ketika daging (daging merah, unggas, ikan) dimasak pada suhu tinggi.</li>\r\n	<li><strong>Pentingnya olahraga</strong>:&nbsp;Olahraga minimal 20 menit sehari sangat penting. Manfaat utamanya meliputi: (a)&nbsp;<strong>Kesehatan Tulang:</strong> Membantu meningkatkan massa dan kepadatan tulang serta mencegah osteoporosis di masa tua. Tulang terus mengalami proses <em>remodeling</em> (penyerapan dan pembentukan kembali) melalui peran sel <strong>osteoblas</strong> (pembentuk tulang baru) dan <strong>osteoklas</strong> (penyerap tulang).&nbsp; Olahraga merangsang hipotalamus-hipofisis anterior untuk mensekresikan <em>growth hormone</em> (hormon pertumbuhan), yang kemudian menghasilkan <em>Insulin-Like Growth Factor&ndash;1</em> (IGF-1). <strong>IGF-1</strong> akan meningkatkan kinerja osteoblas dan menurunkan kinerja osteoklas, sehingga pembentukan tulang lebih tinggi dibandingkan resorpsi tulang. (b)&nbsp;<strong>Pencegahan Diabetes</strong>:&nbsp;Olahraga dapat membakar kalori dimana lemak tubuh akan dibakar dan diubah menjadi kalori sehingga penumpukan lemak tidak berlebihan dan resiko terkena diabetes lebih kecil.</li>\r\n	<li><strong>Kesimbangan Hidup</strong>:&nbsp;Selain memperhatikan pola makan, nilai gizi, dan olahraga, pola hidup sehat juga mencakup tidur yang cukup dan berkualitas. Manfaat akan kita rasakan jika kita memperhatikan istirahat yang cukup untuk tubuh karena tidur yang berkualitas membantu tubuh melakukan regenerasi sel, memperbaiki jaringan yang rusak, dan memproduksi hormon-hormon penting, termasuk hormon pertumbuhan (growth hormone), serta menghasilkan kolagen, yaitu protein yang menjaga elastisitas dan kekencangan kulit.</li>\r\n</ol>\r\n\r\n<p>Mencapai awet muda adalah tentang menerapkan <strong>Pola Hidup Sehat</strong> secara holistik, mencakup nutrisi seimbang, membatasi faktor pemicu penuaan, olahraga teratur, dan istirahat yang cukup. Mari kita biasakan dan menjalankan Pola Hidup Sehat agar hidup lebih bermakna.</p>\r\n', '2025-11-06 04:55:10', 1, 'Pendidikan', 58, '8b521126485d6af2d23f8348495d64f0.jpeg', 1, 'Admin', 0, 'rahasia-awet-muda'),
(38, 'Siswa SMP Islam Al-Hadiriyah Raih Juara 2 Pencak Silat pada Kejuaraan Nasional ASBD 2025', '<p>Prestasi membanggakan kembali diraih oleh salah satu siswa SMP Islam Al-Hadiriyah. Kali ini datang dari cabang olahraga bela diri tradisional, Pencak Silat, dalam ajang Kejuaraan Nasional ASBD (Asosiasi Seni Bela Diri) 2025 yang diselenggarakan di GOR Indoor Stadium Tangerang pada tanggal 9 November 2025</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Siswa bernama Kyandra Prahesta, dari kelas VIII-A, berhasil meraih Juara 2 Nasional setelah melewati berbagai babak penyisihan dan final yang penuh semangat dan sportivitas. Kejuaraan ini diikuti oleh ratusan peserta dari berbagai provinsi di Indonesia, menjadikannya kompetisi yang sangat kompetitif dan bergengsi.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Dalam pertandingan final, Kyandra menunjukkan kemampuan teknik dan mental juang yang luar biasa. Dengan latihan disiplin, ia mampu menampilkan performa terbaiknya hingga mengharumkan nama sekolah di tingkat nasional.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Prestasi ini menunjukkan bahwa siswa SMP Islam Al-Hadiriyah tidak hanya unggul dalam bidang akademik, tetapi juga memiliki semangat tinggi dalam mengembangkan bakat dan minat di bidang olahraga, khususnya bela diri.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Pihak sekolah berharap prestasi ini dapat menjadi inspirasi bagi seluruh siswa untuk terus berlatih, berjuang, dan mengukir prestasi di berbagai bidang, demi membawa nama baik sekolah ke tingkat yang lebih tinggi.</p>\r\n', '2025-11-10 03:29:21', 6, 'Prestasi', 106, '6f304672eb3f5236bd0a41bd1bb43e85.jpeg', 1, 'Admin', 0, 'siswa-smp-islam-al-hadiriyah-raih-juara-2-pencak-silat-pada-kejuaraan-nasional-asbd-2025'),
(39, 'HIGH TEACH HIGH IMPACT', '<p style=\"text-align:justify\">Artikel ini membahas terhadap anak &ndash; anak yang mulai bergantung dengan tekonologi dalam setiap waktu kehidupan mereka yang dihabiskan untuk mengurus hal &ndash; hal yang semu. Tidak ada lagi yang saling tegur sapa dijalanan, ngerumpi bareng teman sepermainan. Dilapangan menjadi semakin sepi, anak &ndash; anak lebih memilih bermain sepak bola dengan komputer.</p>\r\n\r\n<p style=\"text-align:justify\"><em>&ldquo;This word is going crazy by those who adore technology to much. Stop being stick on your gadget. Look up and make the world better place</em>&rdquo;</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Peran HP dalam Kehidupan Anak-Anak</strong></p>\r\n\r\n<p style=\"text-align:justify\">HP telah menjadi alat yang sering digunakan anak-anak untuk bermain game, menonton video, belajar daring, atau berkomunikasi. Teknologi ini bisa sangat membantu, tapi juga bisa berdampak negatif jika digunakan berlebihan.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Transformasi perilaku anak &ndash; anak di Era Digital</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\">Menurunnya Komunikasi di Dunia Nyata</li>\r\n	<li style=\"text-align:justify\">Self Involvements (Narsisme)</li>\r\n	<li style=\"text-align:justify\">Perubahan Metode Pembelajaran di Era Digital</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Efek Sampinhg Ketergantungan Teknologi Pada Anak</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\">Anak mencuri demi bermain Game Online</li>\r\n	<li style=\"text-align:justify\">Terkikisnya interaksi di kehidupan nyata oleh beragam Sosial Media</li>\r\n	<li style=\"text-align:justify\">Cyrberbullying yang mengakibatkan depresi hingga kematian</li>\r\n	<li style=\"text-align:justify\">Kebebasan berpendapat tanpa adanya batasan</li>\r\n	<li style=\"text-align:justify\">Obesitas pada anak &ndash; anak</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Peran Orang Tua</strong></p>\r\n\r\n<p style=\"text-align:justify\">Orang tua harus membuat aturan waktu penggunaan HP, memilih konten yang aman, dan mendampingi anak saat menggunakan teknologi. Edukasi digital yang sehat sangat penting.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Tips Penggunaan HP yang Sehat</strong></p>\r\n\r\n<p style=\"text-align:justify\">Batasi waktu layar (screen time), ajak anak bermain di luar, gunakan parental control, dan jadikan HP sebagai alat bantu belajar, bukan alat hiburan utama.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Kesimpulan</strong></p>\r\n\r\n<p style=\"text-align:justify\">Bahwa teknologi memiliki pengaruh besar dan tidak akan terpisahkan dari kehidupan anak &ndash; anak. Teknologi juga dapat menjadi sarana yang positif untuk belajar, berkreasi, dan mengembangkan kemampuan berpikir jika digunakan secara tepat. Tetapi tanpa pendampingan orang tua teknologi juga dapat berpotensi menimbulkan dampak negative seperti kecanduan, penurunan interaksi sosial, serta gangguan perkembangan emosional dan moral anak. Oleh karena itu peran orang tua dan guru sangatlah penting dalam mengarahkan penggunaan teknologi secara bijak, seimbang dan sesuai usia, supaya teknologi tersebut dapat memberi dampak tinggi yang positif bagi tumbuh kembang anak.</p>\r\n', '2026-01-09 02:56:17', 1, 'Pendidikan', 29, 'b7cf5eb64107beccb2265d98bca47d96.png', 1, 'Admin', 0, 'high-teach-high-impact'),
(40, 'VIRUS OF YOUR MIND', '<p style=\"text-align:justify\">Artikel ini membahas bagaimana membangun persepsi positif untuk menciptakan kehidupan yang lebih baik. Manusia sebagai makhluk sosial dan individu unik memiliki perbedaan dalam latar belakang, pola pikir, dan karakter. Perbedaan ini memengaruhi cara kita memandang dunia serta menilai situasi di sekitar kita.</p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<p><strong>Definisi Persepsi</strong></p>\r\n\r\n<p style=\"text-align:justify\">Persepsi adalah proses mental ketika seseorang menafsirkan dan memberi makna terhadap rangsangan dari lingkungan. Menurut Asrori (2009), persepsi terbentuk dari hasil belajar dan pengalaman hidup yang dialami individu. Dalam kamus psikologi, persepsi juga dijelaskan sebagai kemampuan seseorang dalam menyadari dunia sekitar melalui pengamatan menggunakan pancaindra.</p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<p><strong>Syarat Terbentuknya Persepsi</strong></p>\r\n\r\n<p>Menurut Walgito (1989), ada tiga syarat utama terbentuknya persepsi manusia, yaitu:</p>\r\n\r\n<p>1. Adanya objek yang diamati atau diperhatikan.</p>\r\n\r\n<p>2. Adanya alat indra serta reseptor untuk menerima rangsangan.</p>\r\n\r\n<p>3. Adanya perhatian yang memusatkan pikiran pada objek tersebut.</p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<p><strong>Jenis-Jenis Persepsi</strong></p>\r\n\r\n<p>Persepsi dapat diklasifikasikan berdasarkan fungsi indra manusia, di antaranya:</p>\r\n\r\n<p>1. Persepsi Visual &ndash; melalui penglihatan.</p>\r\n\r\n<p>2. Persepsi Auditori &ndash; melalui pendengaran.</p>\r\n\r\n<p>3. Persepsi Perabaan &ndash; melalui sentuhan.</p>\r\n\r\n<p>4. Persepsi Penciuman &ndash; melalui bau.</p>\r\n\r\n<p>5. Persepsi Pengecapan &ndash; melalui rasa.</p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<p><strong>Memahami Komunikasi Interpersonal</strong></p>\r\n\r\n<p>Komunikasi interpersonal yang efektif berhubungan erat dengan persepsi diri dan orang lain. Joe Luft dan Harry Ingham memperkenalkan model &lsquo;Johari Window&rsquo; yang menjelaskan empat area diri manusia:</p>\r\n\r\n<p>1. Daerah Terbuka &ndash; diketahui diri dan orang lain.</p>\r\n\r\n<p>2. Daerah Buta &ndash; tidak disadari diri namun diketahui orang lain.</p>\r\n\r\n<p>3. Daerah Tersembunyi &ndash; disadari diri tapi disembunyikan dari orang lain.</p>\r\n\r\n<p>4. Daerah Tak Sadar &ndash; tidak diketahui baik oleh diri sendiri maupun orang lain.</p>\r\n\r\n<p>Komunikasi yang sehat perlu dibangun dengan sikap keterbukaan, empati, dukungan, sikap positif, serta kesetaraan agar tercipta hubungan yang harmonis.</p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<p><strong>Ketika Persepsi Menjadi Virus Pikiran</strong></p>\r\n\r\n<p style=\"text-align:justify\">Pikiran manusia layaknya komputer yang dapat terinfeksi virus. Virus tersebut berupa pikiran negatif yang menghambat pertumbuhan pribadi dan membuat seseorang mudah stres atau pesimis. Sebenarnya, setiap individu memiliki kebebasan untuk memilih bagaimana merespons setiap peristiwa. Ketika seseorang memilih berpikir positif, perasaannya pun akan menjadi positif. Sebaliknya, pikiran negatif akan menimbulkan perasaan negatif.</p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<p><strong>Cara Menghapus Virus Pikiran</strong></p>\r\n\r\n<p>Beberapa cara sederhana untuk mengatasi virus dalam pikiran, yaitu:</p>\r\n\r\n<p style=\"text-align:justify\"><strong>1. Self Talk</strong></p>\r\n\r\n<p style=\"text-align:justify\">Biasakan berbicara positif kepada diri sendiri, terutama saat menghadapi tantangan. Gantilah kalimat negatif seperti <em>&ldquo;Aku tidak bisa&rdquo;</em> menjadi <em>&ldquo;Aku sedang belajar agar bisa.&rdquo;</em> Kalimat yang kita ucapkan pada diri sendiri akan memengaruhi cara berpikir dan bertindak. Self talk positif menumbuhkan rasa percaya diri dan membuat pikiran lebih tenang.</p>\r\n\r\n<p style=\"text-align:justify\"><strong>2. Autosuggestion</strong></p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;Tanamkan kalimat afirmatif secara berulang setiap hari, seperti <em>&ldquo;Saya mampu dan layak untuk sukses.&rdquo;</em> Ucapan positif yang terus diulang akan tertanam dalam alam bawah sadar dan perlahan menggantikan pikiran negatif. Teknik ini membantu membangun keyakinan diri, semangat, serta pandangan hidup yang lebih optimis.</p>\r\n\r\n<p style=\"text-align:justify\"><strong>3. Visualization</strong><br />\r\nBayangkan secara jelas situasi positif atau tujuan yang ingin dicapai, misalnya keberhasilan, kebahagiaan, atau ketenangan batin.<br />\r\n&nbsp;</p>\r\n\r\n<p style=\"text-align: justify;\"><strong>Teknik Membangun Persepsi Positif</strong></p>\r\n\r\n<p style=\"text-align:justify\">Untuk menumbuhkan pola pikir yang sehat dan produktif, kita perlu memperhatikan beberapa hal berikut:</p>\r\n\r\n<p>1. Pilih lingkungan yang mendukung dan aman.</p>\r\n\r\n<p>2. Verifikasi kebenaran sumber informasi sebelum mempercayainya.</p>\r\n\r\n<p>3. Lakukan eksperimen dan coba hal baru untuk memperluas wawasan.</p>\r\n\r\n<h2>&nbsp;</h2>\r\n\r\n<p><strong>Kesimpulan</strong></p>\r\n\r\n<p style=\"text-align:justify\">Persepsi memiliki peran penting dalam membentuk cara kita berpikir, merasa, dan bertindak. Dengan melatih diri untuk berpikir positif serta menjaga lingkungan mental yang sehat, kita dapat mencegah masuknya &#39;virus pikiran&#39; yang merusak kebahagiaan dan produktivitas. Pikiran yang jernih dan positif akan membawa kehidupan yang lebih baik, damai, dan bermakna.</p>\r\n', '2026-01-09 02:59:15', 1, 'Pendidikan', 40, '0c642a2164f90f2eb29fdea70ac04c71.png', 1, 'Admin', 0, 'virus-of-your-mind'),
(41, 'ISTIQOMAH: Jalan Menuju Khusnul Khotimah', '<p><strong>Pendahuluan: Sebuah Perenungan Usia</strong></p>\r\n\r\n<p>Menulis tentang istiqomah menjadi sebuah bentuk literasi saat saya memasuki usia mendekati 50 tahun. Jika dihitung berdasarkan penanggalan Hijriah, usia saya sebenarnya sudah melampaui 50 tahun. Melihat banyak rekan seusia yang telah berpulang ke Rahmatullah, muncul perenungan mendalam bahwa kematian adalah sebuah kepastian.</p>\r\n\r\n<p>Pertanyaan besarnya adalah: bagaimana agar kita mendapatkan kematian dalam keadaan <em>khusnul khotimah</em>?. Mengingat perkataan Hujjatul Islam, Abu Hamid Al-Ghazali:</p>\r\n\r\n<p><em>&quot;Orang yang melewati usia 40 tahun, dan kebaikannya tidak melebihi keburukannya, hendaklah ia menyiapkan diri untuk neraka.&quot;</em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Meraih Khusnul Khotimah Melalui Istiqomah</strong></p>\r\n\r\n<p>Cita-cita terbesar setiap Muslim adalah mati dalam keadaan <em>khusnul khotimah</em>. Seseorang dikatakan sukses dalam hidupnya jika ia berhasil mencapai akhir yang baik tersebut. Salah satu doa populer yang sering dipanjatkan untuk memohon ketetapan iman adalah: <em>&ldquo;Wahai Yang Memiliki Keagungan dan Kemuliaan (Allah), matikanlah kami dalam agama Islam.&rdquo;</em></p>\r\n\r\n<p>Untuk meraih kematian yang mulia ini, kita wajib menjalankan hidup dengan <strong>Istiqomah</strong>.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Apa itu Istiqomah?</strong></p>\r\n\r\n<p>Secara sederhana, istiqomah adalah senantiasa konsisten dalam ketaatan kepada Allah. Para sahabat Nabi Muhammad SAW memberikan definisi yang memperdalam makna tersebut:</p>\r\n\r\n<ul>\r\n	<li><strong>Abu Bakar Ash-Shiddiq r.a.:</strong> Konsisten untuk tidak menyekutukan Allah sedikit pun.</li>\r\n	<li><strong>Umar bin Khattab r.a.:</strong> Teguh menjalankan perintah, menjauhi larangan, dan tidak menipu dalam urusan agama.</li>\r\n	<li><strong>Utsman bin Affan r.a.:</strong> Mengikhlaskan amal semata-mata karena Allah.</li>\r\n	<li><strong>Ali bin Abi Thalib r.a.:</strong> Melaksanakan kewajiban dengan sempurna.</li>\r\n</ul>\r\n\r\n<p>Dapat disimpulkan bahwa istiqomah adalah keteguhan hati untuk tetap konsisten dalam ketaatan, menjalankan perintah-Nya, serta menjauhi larangan-Nya.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Buah dan Keutamaan Istiqomah</strong></p>\r\n\r\n<p>Seseorang yang beristiqomah akan mendapatkan anugerah luar biasa dari Allah SWT, di antaranya:</p>\r\n\r\n<ol>\r\n	<li><strong>Ketenangan Hati:</strong> Allah menjanjikan bahwa tidak ada kekhawatiran dan duka cita bagi mereka yang tetap istiqomah (QS. Al-Ahqaf: 13).</li>\r\n	<li><strong>Perlindungan dan Surga:</strong> Malaikat akan turun memberikan kabar gembira berupa perlindungan dari rasa takut dan janji surga (QS. Fussilat: 30).</li>\r\n</ol>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Istiqomah dalam Aspek Sosial</strong></p>\r\n\r\n<p>Istiqomah tidak hanya terbatas pada ritual ibadah, tetapi juga berdampak pada kehidupan sosial. Individu yang konsisten dalam kebaikan akan mendapatkan pengakuan sosial sebagai orang baik dengan sendirinya.</p>\r\n\r\n<p>Hal ini terbukti bahkan pada tokoh dunia di luar Islam yang diakui secara internasional karena konsistensi mereka dalam kemanusiaan, seperti Mother Teresa, Dalai Lama, dan Nelson Mandela.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Penutup</strong></p>\r\n\r\n<p>Imam Ad-Dagog pernah berpesan: <em>&quot;Istiqomah lebih baik daripada seribu karamah.&quot;</em>. Sebagai manusia, kita tidak perlu sibuk mengejar karomah (kemuliaan atau kesaktian), karena yang Tuhan harapkan dari kita adalah tetap istiqomah. Mari kita berupaya menjadi manusia berkualitas dan umat terbaik yang dibanggakan oleh Allah dan Rasul-Nya melalui jalan istiqomah.</p>\r\n', '2026-01-09 03:01:32', 1, 'Pendidikan', 46, 'edac50106cea134aa775bcc783559851.png', 1, 'Admin', 0, 'istiqomah:-jalan-menuju-khusnul-khotimah');
INSERT INTO `tbl_tulisan` (`tulisan_id`, `tulisan_judul`, `tulisan_isi`, `tulisan_tanggal`, `tulisan_kategori_id`, `tulisan_kategori_nama`, `tulisan_views`, `tulisan_gambar`, `tulisan_pengguna_id`, `tulisan_author`, `tulisan_img_slider`, `tulisan_slug`) VALUES
(42, 'Understanding Logical Fallacies: Why Faulty Reasoning Matters in Everyday Life', '<p>In an era dominated by instant information, fast communication, and constant exposure to public opinions, the ability to think critically has become more important than ever. One of the key skills that supports critical thinking is the ability to identify <strong>logical fallacies</strong>, errors in reasoning that weaken an argument. Although they often sound convincing, logical fallacies can mislead audiences, distort facts, and promote arguments that lack a solid foundation.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>What Are Logical Fallacies?</strong></p>\r\n\r\n<p>A logical fallacy is a mistake in reasoning that results in an invalid or unreliable argument. Instead of building their claims on strong evidence and logical structure, individuals who use fallacies rely on misleading connections, emotional manipulation, or oversimplified assumptions. These fallacies may appear persuasive on the surface, but they fail to hold up under careful examination.</p>\r\n\r\n<p>Logical fallacies are sometimes described as &ldquo;mental shortcuts gone wrong,&rdquo; because they usually stem from the human tendency to make quick judgments rather than conduct thorough analysis.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Why Recognizing Logical Fallacies Is Important</strong></p>\r\n\r\n<p>Understanding logical fallacies helps individuals navigate the increasingly complex landscape of modern communication. By learning to spot flawed reasoning, we can:</p>\r\n\r\n<ul>\r\n	<li>Evaluate information more effectively in media, politics, advertisements, and public discussions.</li>\r\n	<li>Avoid being influenced by arguments that are emotionally charged but logically weak.</li>\r\n	<li>Communicate more clearly and build stronger, well-supported arguments.</li>\r\n	<li>Develop habits of critical thinking that lead to better decision-making.</li>\r\n</ul>\r\n\r\n<p>In short, recognizing logical fallacies empowers people to distinguish between sound reasoning and persuasive but misleading claims.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Common Logical Fallacies and Their Examples</strong></p>\r\n\r\n<p>Logical fallacies come in many forms. Below are several of the most frequently encountered types, along with brief examples for clarity.</p>\r\n\r\n<p><strong>1. Ad Hominem</strong></p>\r\n\r\n<p style=\"text-align:left\">This fallacy occurs when an argument attacks the person rather than addressing the point they are making.<br />\r\n<em>Example:</em> &ldquo;Do not trust her opinion on climate change&mdash;she is not an expert.&rdquo;</p>\r\n\r\n<p style=\"text-align:left\">&nbsp;</p>\r\n\r\n<p><strong>2. Straw Man</strong></p>\r\n\r\n<p style=\"text-align:left\">A straw man fallacy misrepresents or exaggerates someone&rsquo;s argument to make it easier to criticize.<br />\r\n<em>Example:</em><br />\r\nA: &ldquo;We need better regulation on social media.&rdquo;<br />\r\nB: &ldquo;So you want to control everything people say online?&rdquo;</p>\r\n\r\n<p style=\"text-align:left\">&nbsp;</p>\r\n\r\n<p><strong>3. Bandwagon</strong></p>\r\n\r\n<p style=\"text-align:left\">This fallacy suggests that a claim must be true or acceptable simply because many people agree with it.<br />\r\n<em>Example:</em> &ldquo;Everyone is using this product, so it must be the best.&rdquo;</p>\r\n\r\n<p style=\"text-align:left\">&nbsp;</p>\r\n\r\n<p><strong>4. Slippery Slope</strong></p>\r\n\r\n<p style=\"text-align:left\">A slippery slope argument assumes that a small initial action will inevitably lead to a chain of negative consequences.<br />\r\n<em>Example:</em> &ldquo;If we allow one exception to the rules, soon no one will follow them.&rdquo;</p>\r\n\r\n<p style=\"text-align:left\">&nbsp;</p>\r\n\r\n<p><strong>5. False Dilemma</strong></p>\r\n\r\n<p>A false dilemma presents only two options, when in fact there are more possibilities.<br />\r\n<em>Example:</em> &ldquo;You either support this policy or you do not care about public safety.&rdquo;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>6. Hasty Generalization</strong></p>\r\n\r\n<p>This fallacy draws a broad conclusion based on insufficient or limited evidence.<br />\r\n<em>Example:</em> &ldquo;One unreliable delivery means all couriers are irresponsible.&rdquo;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>7. Circular Reasoning</strong></p>\r\n\r\n<p style=\"text-align:left\">Circular reasoning uses the conclusion as the basis for the argument.<br />\r\n<em>Example:</em> &ldquo;This brand is trustworthy because it says it is trustworthy.&rdquo;</p>\r\n\r\n<p style=\"text-align:left\">&nbsp;</p>\r\n\r\n<p><strong>8. Red Herring</strong></p>\r\n\r\n<p>A red herring fallacy introduces irrelevant information to distract from the main issue.<br />\r\n<em>Example:</em> &ldquo;Why focus on school discipline when there are global problems to worry about?&rdquo;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>9. Appeal to Emotion</strong></p>\r\n\r\n<p>This fallacy attempts to persuade by manipulating emotions rather than using logical reasoning.<br />\r\n<em>Example:</em> &ldquo;If you truly care about your family, you will buy this insurance.&rdquo;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Logical Fallacies in Everyday Contexts</strong></p>\r\n\r\n<p>Logical fallacies are not limited to academic debates, they appear frequently in everyday conversation, online discussions, advertising, and even casual interactions. For example:</p>\r\n\r\n<ul>\r\n	<li>Influencers may exaggerate claims to persuade followers to buy certain products.</li>\r\n	<li>Social media trends may create pressure to conform, leading to bandwagon thinking.</li>\r\n	<li>Online arguments often shift from discussing issues to attacking individuals.</li>\r\n	<li>Family discussions may rely on fear-based reasoning rather than facts.</li>\r\n</ul>\r\n\r\n<p>These common situations demonstrate how easily flawed reasoning can become part of daily life, reinforcing the importance of critical awareness.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>The Value of Understanding Fallacies</strong></p>\r\n\r\n<p>Logical fallacies have been studied since ancient Greece, with philosophers such as Aristotle documenting the ways in which arguments can mislead. Despite the passage of time, these concepts remain highly relevant. Modern communication especially through digital platforms creates an environment where fallacies can spread quickly and influence public opinion.</p>\r\n\r\n<p>By understanding and recognizing logical fallacies, individuals are better equipped to:</p>\r\n\r\n<ul>\r\n	<li>Engage in respectful and rational discussions.</li>\r\n	<li>Make informed judgments based on reliable evidence.</li>\r\n	<li>Resist manipulation, misinformation, and emotional persuasion.</li>\r\n	<li>Build strong, credible arguments in both personal and professional settings.</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Conclusion</strong></p>\r\n\r\n<p>Logical fallacies may seem subtle, but their impact on public communication and personal interactions is significant. In a world where information circulates rapidly and opinions are easily amplified, the ability to identify faulty reasoning is essential. Developing this skill not only enhances critical thinking but also contributes to more honest, constructive, and meaningful dialogue within society.</p>\r\n', '2026-02-10 03:18:57', 1, 'Pendidikan', 14, '0fe55e702f184f3da24e1f41fd150deb.jpeg', 1, 'Admin', 0, 'understanding-logical-fallacies:-why-faulty-reasoning-matters-in-everyday-life'),
(43, 'TERAPI EMOSI: Seni Menguasai Emosi Tanpa Ribet', '<p style=\"text-align:justify\">Mengulas Kedalaman &quot;Terapi Emosi&quot;: Mengapa Mengelola Perasaan adalah Kunci Kebahagiaan. Dalam perjalanan hidup, emosi adalah kemudi yang menentukan arah tindakan kita. Namun, seringkali kita justru &quot;disetir&quot; oleh emosi tersebut. Buku &quot;Terapi Emosi&quot; karya Rambu Prihatin menawarkan perspektif segar bahwa penyembuhan emosional (emotional healing) tidak harus selalu lewat proses yang rumit dan melelahkan secara akademis.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\">Emotional Healing adalah salah catu cara yang bisa dipilih untuk menekan energi negativ tersebut dan mengelolanya. Emotional Healing adalah sebuah cara yang dilakukan individu untuk membangun energi positif dari emosi-emosi yang sedang ia rasakan. Membangun energi positif tersebut bisa didasarkan pada kebiasaan positif seseorang atau mengikuti cara-cara tertentu seperti meditasi atau terapi.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Berikut adalah poin-poin mendalam yang dieksplorasi dalam upaya mencapai kewarasan jiwa:</strong></p>\r\n\r\n<p style=\"text-align:justify\"><strong>1. Memahami &quot;Emotional Baggage&quot; (Beban Emosi)</strong></p>\r\n\r\n<p style=\"text-align:justify\">Banyak dari kita membawa beban dari masa lalu yang belum tuntas&mdash;entah itu kegagalan, patah hati, atau kritik keras dari orang tua. Buku ini mengajak kita untuk melakukan &quot;inventarisasi emosi&quot;. Tanpa kita sadari, reaksi kita hari ini (seperti mudah marah atau baper) seringkali merupakan proyeksi dari luka lama yang belum sembuh.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>2. Teknik &quot;Tanpa Ribet&quot;: Mindful Living</strong></p>\r\n\r\n<p style=\"text-align:justify\">Sesuai subjudulnya, &quot;Seni Menguasai Emosi Tanpa Ribet&quot;, inti dari metode ini biasanya terletak pada kesadaran penuh (mindfulness). Beberapa cara praktisnya meliputi:</p>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\">Pause (Berhenti Sejenak): Sebelum membalas chat yang memancing emosi atau merespons kritik, berikan jeda 10 detik untuk bernapas.</li>\r\n	<li style=\"text-align:justify\">Labeling (Memberi Nama): Mengatakan &quot;Saya sedang merasa cemas&quot; jauh lebih membantu daripada hanya merasa &quot;sesak&quot; tanpa tahu penyebabnya. Memberi nama pada emosi mengurangi kekuatan emosi tersebut atas diri kita.</li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>3. Pentingnya Self-Compassion (Welas Asih pada Diri Sendiri)</strong></p>\r\n\r\n<p style=\"text-align:justify\">Kita sering menjadi kritikus paling kejam bagi diri sendiri. Buku ini mengingatkan bahwa emotional healing mustahil terjadi jika kita terus menghakimi diri atas kesalahan yang dibuat. Menjadi &quot;sahabat&quot; bagi diri sendiri saat sedang jatuh adalah pondasi utama dari kesehatan jiwa.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>4. Hubungan Antara Emosi dan Fisik</strong></p>\r\n\r\n<p style=\"text-align:justify\">Pernahkah Anda merasa sakit perut saat cemas atau sakit kepala saat stres berat? Tubuh adalah &quot;papan pengumuman&quot; bagi emosi kita. Terapi emosi mengajarkan kita untuk mendengarkan sinyal tubuh. Jika tubuh merasa lelah, itu adalah sinyal bahwa jiwa pun butuh istirahat.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Berikut adalah 10 cara dalam melakukan emotional healing:</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\">Jadilah dirimu sendiri</li>\r\n	<li style=\"text-align:justify\">Ciptakan dirimu</li>\r\n	<li style=\"text-align:justify\">Cinta dan dicintai</li>\r\n	<li style=\"text-align:justify\">Ambil pegangan dipikiran anda</li>\r\n	<li style=\"text-align:justify\">Lupakan masa lalu</li>\r\n	<li style=\"text-align:justify\">Matikan kecemasan</li>\r\n	<li style=\"text-align:justify\">Buat makna</li>\r\n	<li style=\"text-align:justify\">Biarkan makna lebih penting dari pada mood</li>\r\n	<li style=\"text-align:justify\">Upgrade kepribadian anda</li>\r\n	<li style=\"text-align:justify\">Menghadapi keadaan</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>5 contoh emotional healing:</strong></p>\r\n\r\n<ol>\r\n	<li style=\"text-align:justify\">Musik (musik menjadi sebuah pencarian ketika kita ingin memperbaiki emosi atau meningkatkan emosi positif kita)</li>\r\n	<li style=\"text-align:justify\">Tertawa (tertawa menjadi bagian penting dalam hidup, ada saatnya terasa begitu mudah didapatkan, adakalanya menjadi mahal)</li>\r\n	<li style=\"text-align:justify\">Berkeringatlah (berkeringat baik aktivitas olahraga atau membersihkan sesuatu menjadi sebuah hal yang sangat penting dalam bagian emotional healing)</li>\r\n	<li style=\"text-align:justify\">Curhat (curhat dalam bentuk apapun terutama dalam bentuk tulisan membuat kita lebih ingat pengalaman dimasa lalu dan menjadikannya pembelajaran, dan memastikan bahwa diri kita sendiri maupun orang lain tidak melakukan kesalahan yang sama)</li>\r\n	<li style=\"text-align:justify\">Social life (bentuk social life bisa bermacam-macam dan biasanya didasarkan pada hobi masing-masing)</li>\r\n</ol>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\">Jadi buku ini memosisikan untuk memberi gambaran bagaimana emotional healing dapat menjadi alternatif dalam membangun mood positif sampai pada pengelolahan energi-energi negatif.</p>\r\n', '2026-02-10 03:34:48', 1, 'Pendidikan', 30, '08348ffb8e80d1742e28e7609f85c0b2.jpeg', 1, 'Admin', 0, 'terapi-emosi:-seni-menguasai-emosi-tanpa-ribet'),
(44, 'Bersholawat Untuk Mendapatkan Keberkahan Hidup', '<p style=\"text-align:justify\"><strong>Definisi Keberkahan </strong></p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Manusia dalam menghadapi kehidupannya, pasti membutuhkan sebuah keberkahan. Berkah secara definisi mengutip dari perkataan Buya Yahya ialah ziyadah bil khoir tambahan kebaikan yang sifatnya maknawiyah, tidak bisa dilihat oleh mata. Selain itu, berkah juga di definisikan sebagai kebaikan Allah yang senantiasa ada pada semua perkara. Menurut Imam Ghazali berkah merupakan bertambahnya kebaikan. Bagi orang yang beriman, hidup yang berkah merupakan suatu urgensi dalam kehidupan. Keberkahan dalam hidup membuat seseorang merasa cukup akan segala hal yang ia dapatkan.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;<strong>Contoh Keberkahan</strong></p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Mengutip perkataan Buya Yahya beliau mengatakan bahwa contoh berkah ialah ada dua keluarga, yang masing-masing menerima gaji 1 juta dan memiliki dua anak, dari segi makanan yang dihidangkan sama, di sekolahkan di sekolah yang sama, namun dari dua keluarga tersebut ada yang merasa cukup akan hal tersebut, dan satunya lagi merasa serba kekurangan. Contoh yang diberikan oleh Buya Yahya tersebut memberikan gambaran, bahwa dengan keberkahan, kita akan merasa cukup dengan nikmat yang Allah berikan. Salah satu ulama mengatakan bahwa inti hidup bukan tentang angka, tapi tentang keberkahan.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Obsesi Orang Beriman</strong></p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Ustadz Oemar Mita mengatakan bahwa sesungguhnya tidak ada perkara yang paling besar kecuali keberkahan. orang-orang materialisme menetapkan obsesinya paling tinggi itu adalah ketenaran, kemewahan, dan kekayaan. Bagi orang yang beriman bukan itu yang menjadi obsesi tertinggi pada kehidupan kita. Tetapi obsesi tertinggi pada kehidupan kita itu adalah mendapatkan berkah. Apapun yang diberkahi Allah tidak akan mampu dikalahkan oleh apapun, tidak akan mampu dikalahkan oleh kekayaan, dan tidak akan mampu diungguli oleh ketenaran. Apapun yang diberkahi Allah memberikan kenikmatan, memberikan ketenangan, memberikan kelapangan, dan memberikan kebaikan di dalam kehidupan kita.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Sholawat Untuk Mendapatkan Keberkahan Hidup</strong></p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Ada berbagai macam cara seorang hamba untuk mendapatkan berkah yang akan memberikan ketenangan, kebahagiaan dan kebaikan dalam hidupnya. Salah satu cara untuk mendapatkan berkah yang diberikan oleh Allah ialah dengan memperbanyak bersholawat kepada nabi Muhammad shalallahu alaihi wassalam. Sholawat atas Nabi Muhammad shalallahu alaihi wassalam merupakan amal atau kebajikan yang paling utama seperti yang disampaikan oleh Ahmad ibn Al Mubarok dalam kitab Al Ibriz bab XI.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Makna Sholawat</strong></p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Al Hafidz as-Sakhawi mengatakan bahwa sholawat Allah kepada Nabi Muhammad merupakan bukti salah satu keistimewaan Rasulullah shalallahu alaihi wassalam di atas saudara-saudaranya, pada Rasul yang lain.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Ibn Hajar dalam kitabnya al-jauhar Al Munazhzham mengatakan bahwa sholawat dari Allah kepada Nabi Muhammad adalah rahmat yang diikuti dengan penghormatan. Adapun sholawat kita dan sholawat para malaikat kepada nabi Muhammad shalallahu alaihi wassallam merupakan harapan dan permohonan dengan sepenuh hati untuk memohonkan kesempurnaan dan ikut bersuka cita atas segala karuniaNYA yang dianugerahkan kepada beliau.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Anjuran Bersholawat</strong></p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Sholawat merupakan salah satu amal sholeh yang dapat kita lakukan. Anjuran untuk melantunkan sholawat kepada Nabi Muhammad shalallahu alaihi wassalam termaktub dalam surah Al Ahzab ayat 56.</p>\r\n\r\n<p style=\"text-align:justify\">&quot;&lrm;Sesungguhnya Allah dan Malaikat-malaikat-Nya bershalawat untuk Nabi. Wahai orang-orang yang beriman, bershalawatlah kalian untuk Nabi dan ucapkanlah salam hormat kepadanya.&quot;</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Selain surah Al Ahzab ayat 56, Rasulullah menganjurkan umatnya untuk senantiasa bersholawat kepadanya. Rasulullah bersabda: &quot;Barangsiapa yang bersholawat untukku sekali, maka Allah SWT akan bersholawat kepadanya sepuluh kali.&quot; (H.R Muslim).</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Rasulullah bersabda: &quot;Bersholawatlah kalian semua untukku, karena sholawat kalian itu akan membersihkan hati dan menambah kebaikan kalian, dan sesungguhnya pahala sholawat kalian akan dilipatgandakan berkali-kali&quot;.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Rasulullah bersabda: Bersholawatlah kalian semua untukku, karena sesungguhnya Allah SWT akan menyayangimu.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Al Hafidz as-Sakhawi mengutip sebuah riwayat dari Amirul Mukminin Ali Ra Wa Karromallahu Wajhah, bahwa beliau berkata: &quot;Seandainya tidak karena aku akan melupakan dzikrullah azza wa jalla, niscaya aku tidak akan bertaqarrub (mendekatkan diri) kecuali dengan membacakan sholawat atas Nabi Shalallahu alaihi wassalam, karena aku telah mendengar Nabi Shalallahu alaihi wassallam bersabda: Jibril berkata: Barangsiapa membacakan sholawat untukmu sepuluh kali, maka ia akan benar-benar aman dari murkaKu.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Faedah Bersholawat</strong></p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Al-Fasi dalam kitab Hadaiq Al-Anwar mengungkapkan faedah-faedah yang dapat digapai dan dipetik oleh seseorang yang membacakan sholawat untuk Nabi Muhammad shalallahu alaihi wassalam sebagai berikut:</p>\r\n\r\n<p style=\"text-align:justify\">1. &lrm;Mematuhi perintah Allah yang telah menitahkan kita membacakan sholawat untuk Rasulullah</p>\r\n\r\n<p style=\"text-align:justify\">2. &lrm;Tergapainya sepuluh kali sholawat dari Allah SWT bagi orang yang satu kali membacakan sholawat untuk Nabi Shalallahu alaihi wassalam</p>\r\n\r\n<p style=\"text-align:justify\">3. &lrm;Doanya lebih bisa dikabulkan</p>\r\n\r\n<p style=\"text-align:justify\">4. &lrm;Sholawat menjadi alasan utama baginya untuk mendapatkan syafaat dari Rasulullah</p>\r\n\r\n<p style=\"text-align:justify\">5. &lrm;Sholawat penyebab utama bagi terampuninya dosa-dosa dan ditutupinya cela-cela</p>\r\n\r\n<p style=\"text-align:justify\">6. &lrm;Sholawat penyebab pokok dari terpenuhinya segala kebutuhan</p>\r\n\r\n<p style=\"text-align:justify\">7. &lrm;Sholawat penyebab turunnya rahmat Allah</p>\r\n\r\n<p style=\"text-align:justify\">8. &lrm;Sholawat penyebab turunnya barokah</p>\r\n\r\n<p style=\"text-align:justify\">9. &lrm;Sebagai sarana untuk menjaga cinta kepada Rasulullah shalallahu alaihi wassalam</p>\r\n\r\n<p style=\"text-align:justify\">10. &lrm;Sebagai alasan Rasulullah shalallahu alaihi wassalam untuk menyayangi orang yang membacakan sholawat untuk beliau</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Masih banyak lagi faedah-faedah yang akan didapatkan jika seseorang rajin membaca sholawat untuk Rasulullah.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>Ancaman Nabi</strong></p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Rasulullah memberikan peringatan kepada seseorang yang ketika nama beliau diucapkan namun tidak bersholawat kepadanya. Rasulullah bersabda: Orang yang kikir (bakhil) adalah orang yang ketika namaku disebut di sisinya ia tidak membacakan sholawat untukku.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Rasulullah juga bersabda: Barangsiapa yang namaku disebut di sisinya tapi ia tidak membacakan sholawat untukku, maka ia sungguh celaka.</p>\r\n\r\n<p style=\"text-align:justify\">&lrm;Bersholawat kepada nabi memiliki banyak faedah yang akan kita dapatkan jika kita terus memperbanyak untuk membacanya. Salah satu faedahnya ialah sholawat menjadi penyebab turunnya barokah. Barokah atau berkah menjadi inti dari kehidupan orang beriman, maka dengan demikian bersholawat kepada nabi Muhammad shalallahu alaihi wassalam akan menghantarkan kita untuk mendapatkan keberkahan hidup.</p>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><strong>REFERENSI</strong></p>\r\n\r\n<p style=\"text-align:justify\">Noer, Muzammal. 2003. Bersholawat untuk mendapatkan keberkahan hidup. Yogyakarta</p>\r\n\r\n<p style=\"text-align:justify\">Baznas. (2022, 07 Oktober). <em>Makna Berkah dan Ciri Keberkahan</em>. Diakses pada 7 Oktober 2022. https://www.baznasjabar.org/news/makna_berkah_dan_cirinya</p>\r\n', '2026-02-10 03:38:14', 1, 'Pendidikan', 11, '9f4e6a4b0daad4ef437ec4de8ba49197.jpeg', 1, 'Admin', 0, 'bersholawat-untuk-mendapatkan-keberkahan-hidup'),
(45, 'A Moment with Allah: Menikmati Setiap Gerakan Shalat', '<p style=\"text-align: justify;\">Shalat adalah perjalanan jiwa menuju Allah , sebuah panggilan&nbsp; untuk kembali kepadaNya. Adakalanya jiwa kita terasas letih, sholat pun hanya sekedar menjadi rutinitas saja. Sekedar menggugurkan kewajiban . Tubuh kita bergerak,&nbsp; bibir pun melafalkan doa, tetapi hati kita tertinggal entah dimana.</p>\r\n\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n\r\n<p style=\"text-align: justify;\">Kita berdiri di hadapan-Nya, tapi pikiran kita melayang pada urusan dunia. Akhirnya, setelah salam terakhir diucapkan kita pun kembali pada kehidupan yang sama, masih tetap gelisah, masih tetap kosong dan hampa.</p>\r\n\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n\r\n<p style=\"text-align: justify;\">Buku ini adalah ajakan lembut untuk kembali mendekat, bukan sekedar kepada gerakan dan bacaan, melainkan percakapan yang sesungguhnya dengan Allah. Karena shalat bukan hanya kewajiban yang harus ditunaikan tapi seharusnya sholat bias menjadi ruang untuk jiwa yang letih beristirahat, tempat dimana kita bias menumpahkan air mata tanpa malu, tempat dimana kita menemukan jalan pulang.</p>\r\n\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n\r\n<p style=\"text-align: justify;\"><strong>Menyelami Makna Shalat</strong></p>\r\n\r\n<p style=\"text-align: justify;\">Apa itu shalat?</p>\r\n\r\n<p style=\"text-align: justify;\">Sebagian orang akan menjawab; Rangkaian gerakan berdiri, rukuk, sujud dan duduk diantara dua sujud.</p>\r\n\r\n<p style=\"text-align: justify;\">Atau sebagian orang lagi mungkin berkata: Kewajiban lima waktu yang harus ditunaikan agar terhindar dari dosa.</p>\r\n\r\n<p style=\"text-align: justify;\">Secara bahasa, shalat bermakna doa. Allah swt menyebutkan dalam firman-Nya:</p>\r\n\r\n<p style=\"text-align: justify;\">&ldquo;Doakanlah mereka, karena sesungguhnya doamu adalah ketentraman bagi mereka. Allah maha mendengar lagi maha mengetahui.&rdquo; ( QS. At-Taubah:103)</p>\r\n\r\n<p style=\"text-align: justify;\">&nbsp;Shalat adalah doa yang menyatukan hati seorang hamba dengan Rabbnya. Bukan sekedar bacaan, melainkan juga pengaduan jiwa yang haus, permohonan hati yang penuh harap dan percakapan intim dengan Yang Maha Pendengar.</p>\r\n\r\n<p style=\"text-align: justify;\">&nbsp;Secara istilah syari&rsquo;at, para ulama mendefinisikan shalat sebagai ibadah yang khusus yang diawali dengan takbir dan diakhiri dengan salam dan syarat tertentu. Sering kali kita memandang shalat hanya sebagai kewajiban: &ldquo; kalau tidak shalat, aku berdosa&rdquo;. Padahal shalat bukan sekedar kewajiban. Ia adalah undangan penuh cinta dari Allah Swt, kepada hamba-Nya.&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Shalat adalah kebutuhan</strong></p>\r\n\r\n<p>Dalam sebuah diskusi, Profesor Quraish Shihab pernah menyampaikan sebuah pandangan yang sederhana namun dalam maknanya: &ldquo; Orang akan tetap shalat selama masih memiliki rasa cemas dan harap&rdquo;.</p>\r\n\r\n<p>Cemas dan harap adalah dua sisi yang tak pernah lepas dari kehidupan. Cemas terhadap masa depan yang belum pasti, cemas kehilangan orang yang dicintai, cemas terhadap dosa-dosa yang sudah terlanjur dilakukan. Di sisi lain, kita juga hidup dengan harapan keselamatan, keberkahan, rezeki dan ampunan.</p>\r\n\r\n<p>Shalat hadir sebagai jembatan yang menautkan antara cemas dan harap itu dengan Allah Swt.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>Memahami Setiap Gerakan dan Bacaan Shalat</strong></p>\r\n\r\n<p>Setiap shalat dimulai dengan satu kalimat agung: &ldquo;Allahu Akbar&rdquo;. Dua kata sederhana ini bukan sekedar pembuka, melainkan pintu gerbang menuju perjumpaan dengan Sang Pencipta. Saat kita mengangkat kedua tangan kita sejajar dengan pundak atau telinga, kita seolah berkata: &ldquo; Tinggallah kau di belakangku. Mulai saat ini hanya ada aku dan Allah&rdquo;.</p>\r\n\r\n<p>Inilah saat ketika kita memasuki &ldquo;Wilayah Sakral&rdquo; shalat. Segala sesuatu diluar takbiratul ihram adalah dunia; setelahnya, kita telah melangkah kea lam yang lebih tinggi, yaitu alam munajat dengan Allah Swt.</p>\r\n\r\n<p><strong>1. DOA IFTITAH</strong></p>\r\n\r\n<p>Suatu ketika, Ibnu Umar RA berkata, &ldquo; Kami pernah shalat bersama Rasulullah Saw, Tiba-tiba ada seorang jamaah yang berdoa dengan suara lantang:</p>\r\n\r\n<p>Rasulullah Saw kemudia bertanya, &ldquo; Siapa yang mengucapkan kalimat tadi?&rdquo;</p>\r\n\r\n<p>Orang itu menjawab, &ldquo; Saya, ya Rasulullah!&rdquo; Mendengar itu, Rasulullah Saw kemudian bersabda, &ldquo; Aku kagum dengan kalimat itu. Sungguh, kalimat itu mampu membuka pintu-pintu langit.&rdquo;</p>\r\n\r\n<p>Sejak hari itu, Ibnu Umar tidak pernah meninggalkan doa tersebut setiap kali ia berdiri untuk shalat.</p>\r\n\r\n<p>&nbsp;( HR. Muslim).</p>\r\n\r\n<p>Saat kita memulai shalat dengan doa iftitah, sejatinya kita sedang menyambut Allah dengan pujian dan penyerahan diri. Ini adalah moment untuk melepas segala duniawi yang hinggap di hati.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>2.&nbsp;RUKUK</strong></p>\r\n\r\n<p>Punggung lurus sejajar dengan kepala mengajarkan keseimbangan. Yakni tunduk pada Allah Swt dan tegak lurus dalam ketawadhu&rsquo;an.</p>\r\n\r\n<p>Mengapa Allah Swt memerintahkan kita untuk membungkuk? Karena sering kali kita merasa tinggi. Rukuk adalah latihan untuk menundukkan ego, menjinakkan nafsu, dan mengingat hanya Allah satu-satunya yang pantas diangungkan.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>3. I&rsquo;TIDAL</strong></p>\r\n\r\n<p>Setelah belajar merendah. Kini kita belajar bersyukur Karen amasih diberi kesempatan untuk bangkit. Dalam sekejap kita diingatkan bahwa seluruh kemampuan untuk berdiri, bernafas, bahkan untuk melanjutkan shalat ini, semata-mata pemberian Allah Swt.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>4. SUJUD</strong></p>\r\n\r\n<p>Saat kita menundukkan lutut ke bumi, lalu meletakkan kedua tangan, kening dan hidung ke tempat sujud, sejatinya kita sedang menyerahkan diri sepenuhnya kepada Allah sekaligus merasa hina dihadapan-Nya. Namun tetap dalam rasa aman dalam kerendahan karena menemukan kedekatan dengan tuhannya.</p>\r\n\r\n<p>&nbsp;&nbsp; Rasulullah Saw bersabda:</p>\r\n\r\n<p><em>&ldquo;Sedekat-dekatnya seorang hamba dengan Rabb-nya adalah ketika ia sedang sujud, maka perbanyaklah doa.&rdquo; </em></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>5. DUDUK DIANTARA DUA SUJUD</strong></p>\r\n\r\n<p>Gerakan sederhana ini mempunyai makna yang luar biasa didalamnya. Ini adalah symbol kepasrahan total. Dan disini juga kita membaca doa yang sangat dalam maknanya</p>\r\n\r\n<p>&nbsp; &nbsp; &quot;Rabbighfir lii, warhamni, wajburni, warfa&rsquo;ni, warzuqni, wahdini, wa a&rsquo;aafini wa&rsquo;fu &lsquo;anni&quot;.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>Kalimat ini bukan doa biasa. Disini kita diajarkan meminta segalanya kepada Allah Swt:</p>\r\n\r\n<ul>\r\n	<li>Ampunan atas dosa yang lalu (rabbighfirlii).</li>\r\n	<li>Rahmat yang meliputi seluruh hidup kita (warhamnii).</li>\r\n	<li>Kecukupan untuk jiwa yang sering merasa kurang (wajburni).</li>\r\n	<li>Ketinggian derajat yang hanya Allah yang bias anugrahkan (warfa&rsquo;nii).</li>\r\n	<li>Rezeki yang halal dan berkah ( warzuqnii).</li>\r\n	<li>Petunjuk di jalan yang lurus (wahdini).</li>\r\n</ul>\r\n\r\n<p>Saat membacanya, bayangkan kita sedang duduk dihadapan Sang Maha Pemurah yang dapat menagbulkan segala kebutuhan kita.</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>6. TASYAHUD</strong></p>\r\n\r\n<p>Disini kita menyerahkan semua yang agung, seperti kehormatan, kebaikan, dan keberkahan yang hanya untuk Allah Swt. Setiap ucapan ini bagaikan kita sedang mempersembahkan seluruh hidup kita kepada-Nya sebagai bentuk kepasrahan total.</p>\r\n\r\n<p>&nbsp; &nbsp; &quot;Assalaamu &lsquo;alaika ayyuhan nabiyyu warahmatullahi wabarakaatuh.&quot;</p>\r\n\r\n<p><em>&ldquo;Salam, rahmat dan keberkahan Allah semoga tercurah kepadamu, Wahai Nabi.&rdquo;</em></p>\r\n\r\n<p>Bayangkan: Seandainya beliau hadir, apa yang akan kita katakan? Dan ucapan salam ini juga yang akan dibalas oleh Rasululah Saw, sebagaimana sabda beliau:</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp; <em>&ldquo;Tiada seorang pun dari umatku yang memberi salam kepadaku kecuali Allah mengembalikan ruhku kepadaku hingga aku menjawab salamnya.&rdquo; </em>(HR. Abu Dawud dan Ahmad).</p>\r\n\r\n<p>&nbsp;&nbsp;&nbsp;</p>\r\n\r\n<p>Dan terakhir saat salam terucap, jangan merasa bahwa pertemuan dengan Allah telah selesai. Dia tetap dekat, lebih dekat daripada urat leher kita. Selepas salam, tugas kita adalah menjaga rasa itu agar tetap hidup dalam langkah-langkah kita. Salam bukanlah akhir hubungan, melainkan tanda untuk pulang membawa cinta-Nya agar kita aplikasikan dalm setiap kata, sikap, dan perbuatan</p>\r\n', '2026-02-10 04:41:01', 1, 'Pendidikan', 29, 'e7e88e634a30de4180b997d98fe45a4a.png', 1, 'Admin', 0, 'a-moment-with-allah:-menikmati-setiap-gerakan-shalat');

